333→// renderImproveTerminalDryRun writes a styled terminal view of the dry-run friction data.
334→func renderImproveTerminalDryRun(w io.Writer, themes []insightsdb.FrictionTheme, sessionCount, frictionTotal int) {
335→	s := termstyle.New(w)
336→
337→	fmt.Fprintln(w, s.Render(s.Bold, "Entire Improve (dry run)"))
338→	fmt.Fprintf(w, "Analyzed %d sessions | %d friction points | %d patterns found\n\n",
339→		sessionCount, frictionTotal, len(themes))
340→
341→	fmt.Fprintln(w, s.SectionRule("Recurring Friction"))
342→	if len(themes) == 0 {
343→		fmt.Fprintln(w, "  No recurring friction patterns found.")
344→		return
345→	}
346→	for _, t := range themes {
347→		countLine := fmt.Sprintf("  [%dx] %s", t.Count, t.Text)
348→		fmt.Fprintln(w, s.Render(s.Bold, countLine))
349→		if len(t.Sessions) > 0 {
350→			fmt.Fprintln(w, s.Render(s.Gray, "       sessions: "+strings.Join(t.Sessions, ", ")))
351→		}
352→	}
353→}
354→
355→// renderDiff writes a unified diff with colored lines to w.
356→// Lines starting with '+' are rendered in green, '-' in red, '@@' in cyan,
357→// and all other lines in dim.
358→func renderDiff(w io.Writer, s termstyle.Styles, diff string) {
359→	for _, line := range strings.Split(diff, "\n") {
360→		switch {
361→		case strings.HasPrefix(line, "@@"):
362→			fmt.Fprintln(w, s.Render(s.Cyan, line))
363→		case strings.HasPrefix(line, "+"):
364→			fmt.Fprintln(w, s.Render(s.Green, line))
365→		case strings.HasPrefix(line, "-"):
366→			fmt.Fprintln(w, s.Render(s.Red, line))
367→		default:
368→			fmt.Fprintln(w, s.Render(s.Dim, line))
369→		}
370→	}
371→}
