267→// splitCSV splits a GROUP_CONCAT result on commas.
268→func splitCSV(s string) []string {
269→	if s == "" {
270→		return nil
271→	}
272→	var parts []string
273→	start := 0
274→	for i := range len(s) {
275→		if s[i] == ',' {
276→			parts = append(parts, s[start:i])
277→			start = i + 1
278→		}
279→	}
280→	parts = append(parts, s[start:])
281→	return parts
282→}
