199→// nullableString converts an empty string to a SQL NULL value.
200→// Non-empty strings are passed through as-is.
201→func nullableString(s string) interface{} {
202→	if s == "" {
203→		return nil
204→	}
205→	return s
206→}
207→
208→// nullableFloat converts a zero float to a SQL NULL value.
209→// Non-zero floats are passed through as-is.
210→func nullableFloat(f float64) interface{} {
211→	if f == 0 {
212→		return nil
213→	}
214→	return f
215→}
