149→		&row.InputTokens, &row.CacheTokens, &row.OutputTokens, &row.TotalTokens,
150→		&row.APICallCount, &row.DurationMs, &row.TurnCount,
151→		&intent, &outcome, &row.AgentPct,
152→		&overallScore, &tokenEff, &firstPass,
153→		&friction, &focus,
154→	)
155→	if err != nil {
156→		return row, fmt.Errorf("scan session row: %w", err)
157→	}
158→
159→	row.Agent = agent.String
160→	row.Model = model.String
161→	row.Branch = branch.String
162→	row.Intent = intent.String
163→	row.Outcome = outcome.String
164→	row.OverallScore = overallScore.Float64
165→	row.ScoreTokenEff = tokenEff.Float64
166→	row.ScoreFirstPass = firstPass.Float64
167→	row.ScoreFriction = friction.Float64
168→	row.ScoreFocus = focus.Float64
169→
170→	t, err := time.Parse(time.RFC3339, createdAt)
171→	if err != nil {
172→		return row, fmt.Errorf("parse created_at %q: %w", createdAt, err)
173→	}
174→	row.CreatedAt = t
175→	return row, nil
176→}
