 24→	var last int
 25→	var dryRun bool
 26→	var outputJSON bool
 27→
 28→	cmd := &cobra.Command{
 29→		Use:   "improve",
 30→		Short: "Suggest improvements to project context files based on session patterns",
 31→		RunE: func(cmd *cobra.Command, _ []string) error {
 32→			ctx := cmd.Context()
 33→			w := cmd.OutOrStdout()
 34→
 35→			if checkDisabledGuard(ctx, w) {
 36→				return nil
 37→			}
 38→
 39→			if !settings.IsSummarizeEnabled(ctx) {
 40→				fmt.Fprintln(w, "Summarization is required for improve. Enable it in .entire/settings.json:")
 41→				fmt.Fprintln(w, `  { "strategy_options": { "summarize": { "enabled": true } } }`)
 42→				return nil
 43→			}
 44→
 45→			return runImprove(ctx, w, last, dryRun, outputJSON)
 46→		},
 47→	}
 48→
 49→	cmd.Flags().IntVar(&last, "last", 10, "number of recent sessions to analyze")
 50→	cmd.Flags().BoolVar(&dryRun, "dry-run", false, "show friction patterns only, no AI call, no transcript read")
 51→	cmd.Flags().BoolVar(&outputJSON, "json", false, "output as JSON instead of styled terminal output")
 52→
