 56→// runImprove fetches session data from the SQLite cache, refreshes it if stale,
 57→// then analyzes friction patterns and optionally generates context file improvements.
 58→func runImprove(ctx context.Context, w io.Writer, last int, dryRun bool, outputJSON bool) error {
 59→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 60→	if err != nil {
 61→		return fmt.Errorf("not in a git repository: %w", err)
 62→	}
 63→	entireDir := filepath.Join(worktreeRoot, paths.EntireDir)
 64→
 65→	idb, err := insightsdb.Open(filepath.Join(entireDir, "insights.db"))
 66→	if err != nil {
 67→		return fmt.Errorf("open insights cache: %w", err)
 68→	}
 69→	defer func() { _ = idb.Close() }()
 70→
 71→	// Non-fatal: continue with whatever is in the cache.
 72→	refreshCacheIfStale(ctx, idb) //nolint:errcheck,gosec // Non-fatal; continue with stale cache
 73→
 74→	// Phase 1: Query SQLite index for recurring friction themes (2+ occurrences).
 75→	frictionThemes, err := idb.QueryRecurringFriction(ctx, 2)
 76→	if err != nil {
 77→		return fmt.Errorf("query recurring friction: %w", err)
 78→	}
 79→
 80→	// Fetch the last N sessions for summary stats.
 81→	rows, err := idb.QueryLastNSessions(ctx, last)
 82→	if err != nil {
 83→		return fmt.Errorf("query sessions: %w", err)
 84→	}
 85→
 86→	// Count total friction items across all sessions.
 87→	frictionTotal := 0
 88→	for _, r := range rows {
 89→		frictionTotal += len(r.Friction)
 90→	}
 91→
 92→	if dryRun {
 93→		if outputJSON {
 94→			return renderImproveJSONDryRun(w, frictionThemes, len(rows), frictionTotal)
 95→		}
 96→		renderImproveTerminalDryRun(w, frictionThemes, len(rows), frictionTotal)
 97→		return nil
 98→	}
 99→
100→	// Phase 2: Deep-read transcripts for top friction themes.
101→	patterns := buildFrictionPatterns(frictionThemes)
102→	if err = attachTranscriptExcerpts(ctx, idb, patterns, worktreeRoot); err != nil {
103→		// Non-fatal: proceed without transcript excerpts.
104→		_ = err
105→	}
106→
107→	// Phase 3: Detect context files.
108→	contextFiles := improve.DetectContextFiles(worktreeRoot)
109→
110→	// Phase 4: Build analysis from session data + friction patterns, then generate.
111→	summaries := sessionRowsToSummaries(rows)
112→	analysis := improve.AnalyzePatterns(summaries)
113→	// Overlay the transcript excerpts we fetched into the analysis.
114→	applyExcerpts(analysis.RepeatedFriction, patterns)
115→
116→	gen := improve.Generator{Runner: &llmcli.Runner{}}
117→	suggestions, err := gen.Generate(ctx, analysis, contextFiles)
118→	if err != nil {
119→		return fmt.Errorf("generate suggestions: %w", err)
120→	}
121→
122→	report := improve.ImprovementReport{
123→		ContextFiles:  contextFiles,
124→		Suggestions:   suggestions,
125→		SessionsUsed:  len(rows),
126→		FrictionTotal: frictionTotal,
127→		PatternsFound: len(analysis.RepeatedFriction),
128→	}
129→
130→	if outputJSON {
131→		return renderImproveJSON(w, report)
132→	}
133→	renderImproveTerminal(w, report)
134→	return nil
135→}
