137→// buildFrictionPatterns converts insightsdb friction themes to improve.FrictionPattern values.
138→func buildFrictionPatterns(themes []insightsdb.FrictionTheme) []improve.FrictionPattern {
139→	patterns := make([]improve.FrictionPattern, 0, len(themes))
140→	for _, t := range themes {
141→		patterns = append(patterns, improve.FrictionPattern{
142→			Theme:            t.Text,
143→			Count:            t.Count,
144→			AffectedSessions: t.Sessions,
145→		})
146→	}
147→	return patterns
148→}
149→
150→// attachTranscriptExcerpts fetches transcript excerpts for top friction themes and
151→// attaches them to the corresponding patterns in-place.
152→// Errors are non-fatal; unreadable sessions are silently skipped.
153→func attachTranscriptExcerpts(ctx context.Context, idb *insightsdb.InsightsDB, patterns []improve.FrictionPattern, _ string) error {
154→	repo, err := openRepository(ctx)
155→	if err != nil {
156→		return fmt.Errorf("open git repository: %w", err)
157→	}
158→	store := checkpoint.NewGitStore(repo)
159→
160→	// Limit to top 3 friction themes.
161→	limit := 3
162→	if len(patterns) < limit {
163→		limit = len(patterns)
164→	}
165→
166→	for i := range patterns[:limit] {
167→		cpIDs, queryErr := idb.QuerySessionsWithFriction(ctx, "%"+patterns[i].Theme+"%")
168→		if queryErr != nil {
169→			continue
170→		}
171→
172→		// Limit to top 2 sessions per theme.
173→		sessionLimit := 2
174→		if len(cpIDs) < sessionLimit {
175→			sessionLimit = len(cpIDs)
176→		}
177→
178→		var excerpts []string
179→		for _, cpIDStr := range cpIDs[:sessionLimit] {
180→			cpID, parseErr := checkpointid.NewCheckpointID(cpIDStr)
181→			if parseErr != nil {
182→				continue
183→			}
184→
185→			content, readErr := store.ReadSessionContent(ctx, cpID, 0)
186→			if readErr != nil {
187→				continue
188→			}
189→
190→			condensed, buildErr := summarize.BuildCondensedTranscriptFromBytes(content.Transcript, content.Metadata.Agent)
191→			if buildErr != nil || len(condensed) == 0 {
192→				continue
193→			}
194→
195→			formatted := summarize.FormatCondensedTranscript(summarize.Input{Transcript: condensed})
196→			excerpt := truncateString(formatted, 2000)
197→			if excerpt != "" {
198→				excerpts = append(excerpts, excerpt)
199→			}
200→		}
201→
202→		if len(excerpts) > 0 {
203→			patterns[i].TranscriptExcerpt = strings.Join(excerpts, "\n---\n")
204→		}
205→	}
206→
207→	return nil
208→}
209→
210→// applyExcerpts copies TranscriptExcerpt values from src patterns into dst patterns
211→// by matching on theme text.
212→func applyExcerpts(dst []improve.FrictionPattern, src []improve.FrictionPattern) {
213→	excerptByTheme := make(map[string]string, len(src))
214→	for _, p := range src {
215→		if p.TranscriptExcerpt != "" {
216→			excerptByTheme[p.Theme] = p.TranscriptExcerpt
217→		}
218→	}
219→	for i := range dst {
220→		if excerpt, ok := excerptByTheme[dst[i].Theme]; ok {
221→			dst[i].TranscriptExcerpt = excerpt
222→		}
223→	}
224→}
