355→// renderDiff writes a unified diff with colored lines to w.
356→// Lines starting with '+' are rendered in green, '-' in red, '@@' in cyan,
357→// and all other lines in dim.
358→func renderDiff(w io.Writer, s termstyle.Styles, diff string) {
359→	for _, line := range strings.Split(diff, "\n") {
360→		switch {
361→		case strings.HasPrefix(line, "@@"):
362→			fmt.Fprintln(w, s.Render(s.Cyan, line))
363→		case strings.HasPrefix(line, "+"):
364→			fmt.Fprintln(w, s.Render(s.Green, line))
365→		case strings.HasPrefix(line, "-"):
366→			fmt.Fprintln(w, s.Render(s.Red, line))
367→		default:
368→			fmt.Fprintln(w, s.Render(s.Dim, line))
369→		}
370→	}
371→}
