 43→// QueryRecurringFriction returns friction themes occurring at least minCount times,
 44→// ordered by count descending.
 45→func (idb *InsightsDB) QueryRecurringFriction(ctx context.Context, minCount int) ([]FrictionTheme, error) {
 46→	rows, err := idb.db.QueryContext(ctx, `
 47→		SELECT text, COUNT(*) AS cnt, GROUP_CONCAT(DISTINCT checkpoint_id) AS sessions
 48→		FROM friction
 49→		GROUP BY text
 50→		HAVING cnt >= ?
 51→		ORDER BY cnt DESC
 52→	`, minCount)
 53→	if err != nil {
 54→		return nil, fmt.Errorf("query recurring friction: %w", err)
 55→	}
 56→	defer rows.Close()
 57→
 58→	var themes []FrictionTheme
 59→	for rows.Next() {
 60→		var theme FrictionTheme
 61→		var sessionsCSV string
 62→		if err = rows.Scan(&theme.Text, &theme.Count, &sessionsCSV); err != nil {
 63→			return nil, fmt.Errorf("scan friction theme: %w", err)
 64→		}
 65→		theme.Sessions = splitCSV(sessionsCSV)
 66→		themes = append(themes, theme)
 67→	}
 68→	if err = rows.Err(); err != nil {
 69→		return nil, fmt.Errorf("iterate friction themes: %w", err)
 70→	}
 71→	return themes, nil
 72→}
