100→// sessionColumns is the ordered column list for SELECT queries on the sessions table.
101→const sessionColumns = `
102→	checkpoint_id, session_id, session_index,
103→	agent, model, branch, created_at,
104→	input_tokens, cache_tokens, output_tokens, total_tokens,
105→	api_call_count, duration_ms, turn_count,
106→	intent, outcome, agent_percentage,
107→	overall_score, score_token_efficiency, score_first_pass,
108→	score_friction, score_focus`
109→
110→// querySessions executes a SELECT on sessions with the given args,
111→// then populates denormalized fields for each row.
112→func (idb *InsightsDB) querySessions(ctx context.Context, query string, args ...interface{}) ([]SessionRow, error) {
113→	rows, err := idb.db.QueryContext(ctx, query, args...)
114→	if err != nil {
115→		return nil, fmt.Errorf("query sessions: %w", err)
116→	}
117→	defer rows.Close()
118→
119→	var sessions []SessionRow
120→	for rows.Next() {
121→		row, err := scanSession(rows)
122→		if err != nil {
123→			return nil, err
124→		}
125→		sessions = append(sessions, row)
126→	}
127→	if err = rows.Err(); err != nil {
128→		return nil, fmt.Errorf("iterate sessions: %w", err)
129→	}
130→
131→	for i := range sessions {
132→		if err = idb.populateDenormalized(ctx, &sessions[i]); err != nil {
133→			return nil, err
134→		}
135→	}
136→	return sessions, nil
137→}
138→
139→// scanSession reads one row from the sessions table into a SessionRow.
140→func scanSession(rows *sql.Rows) (SessionRow, error) {
141→	var row SessionRow
142→	var createdAt string
143→	var agent, model, branch, intent, outcome sql.NullString
144→	var overallScore, tokenEff, firstPass, friction, focus sql.NullFloat64
145→
146→	err := rows.Scan(
147→		&row.CheckpointID, &row.SessionID, &row.SessionIndex,
148→		&agent, &model, &branch, &createdAt,
149→		&row.InputTokens, &row.CacheTokens, &row.OutputTokens, &row.TotalTokens,
150→		&row.APICallCount, &row.DurationMs, &row.TurnCount,
151→		&intent, &outcome, &row.AgentPct,
152→		&overallScore, &tokenEff, &firstPass,
153→		&friction, &focus,
154→	)
155→	if err != nil {
156→		return row, fmt.Errorf("scan session row: %w", err)
157→	}
158→
159→	row.Agent = agent.String
160→	row.Model = model.String
161→	row.Branch = branch.String
162→	row.Intent = intent.String
163→	row.Outcome = outcome.String
164→	row.OverallScore = overallScore.Float64
165→	row.ScoreTokenEff = tokenEff.Float64
166→	row.ScoreFirstPass = firstPass.Float64
167→	row.ScoreFriction = friction.Float64
168→	row.ScoreFocus = focus.Float64
169→
170→	t, err := time.Parse(time.RFC3339, createdAt)
171→	if err != nil {
172→		return row, fmt.Errorf("parse created_at %q: %w", createdAt, err)
173→	}
174→	row.CreatedAt = t
175→	return row, nil
176→}
