182→	if err != nil {
183→		return err
184→	}
185→	row.Friction, err = idb.loadFriction(ctx, row.CheckpointID, row.SessionIndex)
186→	if err != nil {
187→		return err
188→	}
189→	row.Learnings, err = idb.loadLearnings(ctx, row.CheckpointID, row.SessionIndex)
190→	return err
191→}
