131→// Load loads the Entire settings from .entire/settings.json,
132→// then applies any overrides from .entire/settings.local.json if it exists.
133→// Returns default settings if neither file exists.
134→// Works correctly from any subdirectory within the repository.
135→func Load(ctx context.Context) (*EntireSettings, error) {
136→	// Get absolute paths for settings files
137→	settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
138→	if err != nil {
139→		settingsFileAbs = EntireSettingsFile // Fallback to relative
140→	}
141→	localSettingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
142→	if err != nil {
143→		localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
144→	}
145→
146→	// Load base settings
147→	settings, err := loadFromFile(settingsFileAbs)
148→	if err != nil {
149→		return nil, fmt.Errorf("reading settings file: %w", err)
150→	}
151→
152→	// Apply local overrides if they exist
153→	localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
154→	if err != nil {
155→		if !os.IsNotExist(err) {
156→			return nil, fmt.Errorf("reading local settings file: %w", err)
157→		}
158→		// Local file doesn't exist, continue without overrides
159→	} else {
160→		if err := mergeJSON(settings, localData); err != nil {
161→			return nil, fmt.Errorf("merging local settings: %w", err)
162→		}
163→	}
164→
165→	return settings, nil
166→}
