204→// mergeJSON merges JSON data into existing settings.
205→// Only non-zero values from the JSON override existing settings.
206→func mergeJSON(settings *EntireSettings, data []byte) error {
207→	// First, validate that there are no unknown keys using strict decoding
208→	dec := json.NewDecoder(bytes.NewReader(data))
209→	dec.DisallowUnknownFields()
210→	var temp EntireSettings
211→	if err := dec.Decode(&temp); err != nil {
212→		return fmt.Errorf("parsing JSON: %w", err)
213→	}
214→
215→	// Parse into a map to check which fields are present
216→	var raw map[string]json.RawMessage
217→	if err := json.Unmarshal(data, &raw); err != nil {
218→		return fmt.Errorf("parsing JSON: %w", err)
219→	}
220→
221→	// Override enabled if present
222→	if enabledRaw, ok := raw["enabled"]; ok {
223→		var e bool
224→		if err := json.Unmarshal(enabledRaw, &e); err != nil {
225→			return fmt.Errorf("parsing enabled field: %w", err)
226→		}
227→		settings.Enabled = e
228→	}
229→
230→	// Override local_dev if present
231→	if localDevRaw, ok := raw["local_dev"]; ok {
232→		var ld bool
233→		if err := json.Unmarshal(localDevRaw, &ld); err != nil {
234→			return fmt.Errorf("parsing local_dev field: %w", err)
235→		}
236→		settings.LocalDev = ld
237→	}
238→
239→	// Override absolute_git_hook_path if present
240→	if ahpRaw, ok := raw["absolute_git_hook_path"]; ok {
241→		var ahp bool
242→		if err := json.Unmarshal(ahpRaw, &ahp); err != nil {
243→			return fmt.Errorf("parsing absolute_git_hook_path field: %w", err)
244→		}
245→		settings.AbsoluteGitHookPath = ahp
246→	}
247→
248→	// Override log_level if present and non-empty
249→	if logLevelRaw, ok := raw["log_level"]; ok {
250→		var ll string
251→		if err := json.Unmarshal(logLevelRaw, &ll); err != nil {
252→			return fmt.Errorf("parsing log_level field: %w", err)
253→		}
254→		if ll != "" {
255→			settings.LogLevel = ll
256→		}
257→	}
258→
259→	// Merge strategy_options if present
260→	if optionsRaw, ok := raw["strategy_options"]; ok {
261→		var opts map[string]any
262→		if err := json.Unmarshal(optionsRaw, &opts); err != nil {
263→			return fmt.Errorf("parsing strategy_options field: %w", err)
264→		}
265→		if settings.StrategyOptions == nil {
266→			settings.StrategyOptions = opts
267→		} else {
268→			for k, v := range opts {
269→				settings.StrategyOptions[k] = v
270→			}
271→		}
272→	}
273→
274→	// Override telemetry if present
275→	if telemetryRaw, ok := raw["telemetry"]; ok {
276→		var t bool
277→		if err := json.Unmarshal(telemetryRaw, &t); err != nil {
278→			return fmt.Errorf("parsing telemetry field: %w", err)
279→		}
280→		settings.Telemetry = &t
281→	}
282→
283→	// Merge redaction sub-fields if present (field-level, not wholesale replace).
284→	if redactionRaw, ok := raw["redaction"]; ok {
285→		if settings.Redaction == nil {
286→			settings.Redaction = &RedactionSettings{}
287→		}
288→		if err := mergeRedaction(settings.Redaction, redactionRaw); err != nil {
289→			return fmt.Errorf("parsing redaction field: %w", err)
290→		}
291→	}
292→
293→	// Override commit_linking if present and non-empty
294→	if commitLinkingRaw, ok := raw["commit_linking"]; ok {
295→		var cl string
296→		if err := json.Unmarshal(commitLinkingRaw, &cl); err != nil {
297→			return fmt.Errorf("parsing commit_linking field: %w", err)
298→		}
299→		if cl != "" {
300→			switch cl {
301→			case CommitLinkingAlways, CommitLinkingPrompt:
302→				settings.CommitLinking = cl
303→			default:
304→				return fmt.Errorf("invalid commit_linking value %q: must be %q or %q", cl, CommitLinkingAlways, CommitLinkingPrompt)
305→			}
306→		}
307→	}
308→
309→	// Override external_agents if present
310→	if externalAgentsRaw, ok := raw["external_agents"]; ok {
311→		var ea bool
312→		if err := json.Unmarshal(externalAgentsRaw, &ea); err != nil {
313→			return fmt.Errorf("parsing external_agents field: %w", err)
314→		}
315→		settings.ExternalAgents = ea
316→	}
317→
318→	// Override evolve if present
319→	if evolveRaw, ok := raw["evolve"]; ok {
320→		var ev EvolveSettings
321→		if err := json.Unmarshal(evolveRaw, &ev); err != nil {
322→			return fmt.Errorf("parsing evolve field: %w", err)
323→		}
324→		settings.EvolveConfig = &ev
325→	}
326→
327→	return nil
328→}
