340→// turnCountFromState extracts the turn count from session state.
341→func turnCountFromState(state *SessionState) int {
342→	if state.SessionTurnCount > 0 {
343→		return state.SessionTurnCount
344→	}
345→	return state.StepCount // fallback to checkpoint count
346→}
347→
348→func hasTokenUsageData(usage *agent.TokenUsage) bool {
349→	if usage == nil {
350→		return false
351→	}
352→
353→	if usage.InputTokens > 0 || usage.CacheCreationTokens > 0 || usage.CacheReadTokens > 0 || usage.OutputTokens > 0 || usage.APICallCount > 0 {
354→		return true
355→	}
356→
357→	return hasTokenUsageData(usage.SubagentTokens)
358→}
