382→// attributionOpts provides pre-resolved git objects to avoid redundant reads.
383→type attributionOpts struct {
384→	headTree              *object.Tree // HEAD commit tree (already resolved by PostCommit)
385→	shadowTree            *object.Tree // Shadow branch tree (already resolved by PostCommit)
386→	repoDir               string       // Repository worktree path for git CLI commands
387→	attributionBaseCommit string       // Base commit hash for non-agent file detection (empty = fall back to go-git tree walk)
388→	headCommitHash        string       // HEAD commit hash for non-agent file detection (empty = fall back to go-git tree walk)
389→}
390→
391→func calculateSessionAttributions(ctx context.Context, repo *git.Repository, shadowRef *plumbing.Reference, sessionData *ExtractedSessionData, state *SessionState, opts ...attributionOpts) *cpkg.InitialAttribution {
392→	// Calculate initial attribution using accumulated prompt attribution data.
393→	// This uses user edits captured at each prompt start (before agent works),
394→	// plus any user edits after the final checkpoint (shadow → head).
395→	//
396→	// When shadowRef is nil (agent committed mid-turn before SaveStep),
397→	// HEAD is used as the shadow tree. This is correct because the agent's
398→	// commit IS HEAD — there are no user edits between agent work and commit.
399→	logCtx := logging.WithComponent(ctx, "attribution")
400→
401→	var o attributionOpts
402→	if len(opts) > 0 {
403→		o = opts[0]
404→	}
405→
406→	headTree := o.headTree
407→	if headTree == nil {
408→		headRef, headErr := repo.Head()
409→		if headErr != nil {
410→			logging.Debug(logCtx, "attribution skipped: failed to get HEAD",
411→				slog.String("error", headErr.Error()))
412→			return nil
413→		}
414→
415→		headCommit, commitErr := repo.CommitObject(headRef.Hash())
416→		if commitErr != nil {
417→			logging.Debug(logCtx, "attribution skipped: failed to get HEAD commit",
418→				slog.String("error", commitErr.Error()))
419→			return nil
420→		}
421→
422→		var treeErr error
423→		headTree, treeErr = headCommit.Tree()
424→		if treeErr != nil {
425→			logging.Debug(logCtx, "attribution skipped: failed to get HEAD tree",
426→				slog.String("error", treeErr.Error()))
427→			return nil
428→		}
429→	}
430→
431→	// Get shadow tree: from pre-resolved cache, shadow branch, or HEAD (agent committed directly).
432→	shadowTree := o.shadowTree
433→	if shadowTree == nil {
434→		if shadowRef != nil {
435→			shadowCommit, shadowErr := repo.CommitObject(shadowRef.Hash())
436→			if shadowErr != nil {
437→				logging.Debug(logCtx, "attribution skipped: failed to get shadow commit",
438→					slog.String("error", shadowErr.Error()),
439→					slog.String("shadow_ref", shadowRef.Hash().String()))
440→				return nil
441→			}
442→			var shadowTreeErr error
443→			shadowTree, shadowTreeErr = shadowCommit.Tree()
444→			if shadowTreeErr != nil {
445→				logging.Debug(logCtx, "attribution skipped: failed to get shadow tree",
446→					slog.String("error", shadowTreeErr.Error()))
447→				return nil
448→			}
449→		} else {
450→			// No shadow branch: agent committed mid-turn. Use HEAD as shadow
451→			// because the agent's work is the commit itself.
452→			logging.Debug(logCtx, "attribution: using HEAD as shadow (no shadow branch)")
453→			shadowTree = headTree
454→		}
455→	}
456→
457→	// Get base tree (state before session started)
458→	var baseTree *object.Tree
459→	attrBase := state.AttributionBaseCommit
460→	if attrBase == "" {
461→		attrBase = state.BaseCommit // backward compat
462→	}
463→	if baseCommit, baseErr := repo.CommitObject(plumbing.NewHash(attrBase)); baseErr == nil {
464→		if tree, baseTErr := baseCommit.Tree(); baseTErr == nil {
465→			baseTree = tree
466→		} else {
467→			logging.Debug(logCtx, "attribution: base tree unavailable",
468→				slog.String("error", baseTErr.Error()))
469→		}
470→	} else {
471→		logging.Debug(logCtx, "attribution: base commit unavailable",
472→			slog.String("error", baseErr.Error()),
473→			slog.String("attribution_base", attrBase))
474→	}
475→
476→	// Log accumulated prompt attributions for debugging
477→	var totalUserAdded, totalUserRemoved int
478→	for i, pa := range state.PromptAttributions {
479→		totalUserAdded += pa.UserLinesAdded
480→		totalUserRemoved += pa.UserLinesRemoved
481→		logging.Debug(logCtx, "prompt attribution data",
482→			slog.Int("checkpoint", pa.CheckpointNumber),
483→			slog.Int("user_added", pa.UserLinesAdded),
484→			slog.Int("user_removed", pa.UserLinesRemoved),
485→			slog.Int("agent_added", pa.AgentLinesAdded),
486→			slog.Int("agent_removed", pa.AgentLinesRemoved),
487→			slog.Int("index", i))
488→	}
489→
490→	attribution := CalculateAttributionWithAccumulated(
491→		ctx,
492→		baseTree,
493→		shadowTree,
494→		headTree,
495→		sessionData.FilesTouched,
496→		state.PromptAttributions,
497→		o.repoDir,
498→		o.attributionBaseCommit,
499→		o.headCommitHash,
500→	)
501→
502→	if attribution != nil {
503→		logging.Info(logCtx, "attribution calculated",
504→			slog.Int("agent_lines", attribution.AgentLines),
505→			slog.Int("human_added", attribution.HumanAdded),
506→			slog.Int("human_modified", attribution.HumanModified),
507→			slog.Int("human_removed", attribution.HumanRemoved),
508→			slog.Int("total_committed", attribution.TotalCommitted),
509→			slog.Float64("agent_percentage", attribution.AgentPercentage),
510→			slog.Int("accumulated_user_added", totalUserAdded),
511→			slog.Int("accumulated_user_removed", totalUserRemoved),
512→			slog.Int("files_touched", len(sessionData.FilesTouched)))
513→	}
514→
515→	return attribution
516→}
517→
518→// extractSessionData extracts session data from the shadow branch.
519→// filesTouched is the list of files tracked during the session (from SessionState.FilesTouched).
520→// agentType identifies the agent (e.g., "Gemini CLI", "Claude Code") to determine transcript format.
521→// liveTranscriptPath, when non-empty and readable, is preferred over the shadow branch copy.
522→// This handles the case where SaveStep was skipped (no code changes) but the transcript
523→// continued growing — the shadow branch copy would be stale.
524→// checkpointTranscriptStart is the line offset (Claude) or message index (Gemini) where the current checkpoint began.
525→func (s *ManualCommitStrategy) extractSessionData(ctx context.Context, repo *git.Repository, shadowRef plumbing.Hash, sessionID string, filesTouched []string, agentType types.AgentType, liveTranscriptPath string, checkpointTranscriptStart int, isActive bool) (*ExtractedSessionData, error) {
526→	ag, _ := agent.GetByAgentType(agentType) //nolint:errcheck // ag may be nil for unknown agent types; callers use type assertions so nil is safe
527→	commit, err := repo.CommitObject(shadowRef)
528→	if err != nil {
529→		return nil, fmt.Errorf("failed to get commit object: %w", err)
530→	}
531→
532→	tree, err := commit.Tree()
533→	if err != nil {
534→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
535→	}
536→
537→	data := &ExtractedSessionData{}
538→	// sessionID is already an "entire session ID" (with date prefix)
539→	metadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
540→
541→	// Extract transcript — prefer the live file when available, fall back to shadow branch.
542→	// The shadow branch copy may be stale if the last turn ended without code changes
543→	// (SaveStep is only called when there are file modifications).
544→	var fullTranscript string
545→	if liveTranscriptPath != "" {
546→		// Ensure transcript file exists (OpenCode creates it lazily via `opencode export`).
547→		// Only wait for flush when the session is active — for idle/ended sessions the
548→		// transcript is already fully flushed (the Stop hook completed the flush).
549→		if isActive {
550→			prepareTranscriptIfNeeded(ctx, ag, liveTranscriptPath)
551→		}
552→		if liveData, readErr := os.ReadFile(liveTranscriptPath); readErr == nil && len(liveData) > 0 { //nolint:gosec // path from session state
553→			fullTranscript = string(liveData)
554→		}
555→	}
556→	if fullTranscript == "" {
557→		// Fall back to shadow branch copy
558→		if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileName); fileErr == nil {
559→			if content, contentErr := file.Contents(); contentErr == nil {
560→				fullTranscript = content
561→			}
562→		} else if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileNameLegacy); fileErr == nil {
563→			if content, contentErr := file.Contents(); contentErr == nil {
564→				fullTranscript = content
565→			}
566→		}
567→	}
568→
569→	// Process transcript based on agent type
570→	if fullTranscript != "" {
571→		data.Transcript = []byte(fullTranscript)
572→		data.FullTranscriptLines = countTranscriptItems(agentType, fullTranscript)
573→		// Read prompts from shadow branch tree (source of truth after SaveStep)
574→		if file, fileErr := tree.File(metadataDir + "/" + paths.PromptFileName); fileErr == nil {
575→			if content, contentErr := file.Contents(); contentErr == nil && content != "" {
576→				data.Prompts = splitPromptContent(content)
577→			}
578→		}
579→		// Filesystem fallback (written at turn start, covers mid-turn commits)
580→		if len(data.Prompts) == 0 {
581→			data.Prompts = readPromptsFromFilesystem(ctx, sessionID)
582→		}
583→	}
584→
585→	// Use tracked files from session state (not all files in tree)
586→	data.FilesTouched = filesTouched
587→
588→	// Calculate token usage from the extracted transcript portion
589→	if len(data.Transcript) > 0 {
590→		data.TokenUsage = agent.CalculateTokenUsage(ctx, ag, data.Transcript, checkpointTranscriptStart, "") //TODO: why do we not use here subagents dir?
591→	}
592→
593→	return data, nil
594→}
595→
596→// extractSessionDataFromLiveTranscript extracts session data directly from the live transcript file.
597→// This is used for mid-session commits where no shadow branch exists yet.
598→func (s *ManualCommitStrategy) extractSessionDataFromLiveTranscript(ctx context.Context, state *SessionState) (*ExtractedSessionData, error) {
599→	data := &ExtractedSessionData{}
600→
601→	ag, _ := agent.GetByAgentType(state.AgentType) //nolint:errcheck // ag may be nil for unknown agent types; callers use type assertions so nil is safe
602→
603→	// Resolve the transcript path (handles agents that relocate mid-session).
604→	transcriptPath, resolveErr := resolveTranscriptPath(state)
605→	if resolveErr != nil {
606→		return nil, resolveErr
607→	}
608→
609→	liveData, err := os.ReadFile(transcriptPath) //nolint:gosec // path validated by resolveTranscriptPath
610→	if err != nil {
611→		return nil, fmt.Errorf("failed to read live transcript: %w", err)
612→	}
613→
614→	if len(liveData) == 0 {
615→		return nil, errors.New("live transcript is empty")
616→	}
617→
618→	fullTranscript := string(liveData)
619→	data.Transcript = liveData
620→	data.FullTranscriptLines = countTranscriptItems(state.AgentType, fullTranscript)
621→	data.Prompts = readPromptsFromFilesystem(ctx, state.SessionID)
622→
623→	// Resolve files touched: prefers hook-populated state, falls back to transcript extraction
624→	data.FilesTouched = s.resolveFilesTouched(ctx, state)
625→
626→	// Calculate token usage from the extracted transcript portion
627→	if len(data.Transcript) > 0 {
628→		data.TokenUsage = agent.CalculateTokenUsage(ctx, ag, data.Transcript, state.CheckpointTranscriptStart, "") //TODO: why do we not use here subagents dir?
629→	}
630→
631→	return data, nil
632→}
633→
634→// countTranscriptItems counts lines (JSONL) or messages (JSON) in a transcript.
635→// For Claude Code and JSONL-based agents, this counts lines.
636→// For Gemini CLI, OpenCode, and JSON-based agents, this counts messages.
637→// Returns 0 if the content is empty or malformed.
638→func countTranscriptItems(agentType types.AgentType, content string) int {
639→	if content == "" {
640→		return 0
641→	}
642→
643→	// OpenCode uses export JSON format with {"info": {...}, "messages": [...]}
644→	if agentType == agent.AgentTypeOpenCode {
645→		session, err := opencode.ParseExportSession([]byte(content))
646→		if err == nil && session != nil {
647→			return len(session.Messages)
648→		}
649→		return 0
650→	}
651→
652→	// Try Gemini format first if agentType is Gemini, or as fallback if Unknown
653→	if agentType == agent.AgentTypeGemini || agentType == agent.AgentTypeUnknown {
654→		transcript, err := geminicli.ParseTranscript([]byte(content))
655→		if err == nil && transcript != nil && len(transcript.Messages) > 0 {
656→			return len(transcript.Messages)
657→		}
658→		// If agentType is explicitly Gemini but parsing failed, return 0
659→		if agentType == agent.AgentTypeGemini {
660→			return 0
661→		}
662→		// Otherwise fall through to JSONL parsing for Unknown type
663→	}
664→
665→	// Claude Code and other JSONL-based agents
666→	allLines := strings.Split(content, "\n")
667→	// Trim trailing empty lines (from final \n in JSONL)
668→	for len(allLines) > 0 && strings.TrimSpace(allLines[len(allLines)-1]) == "" {
669→		allLines = allLines[:len(allLines)-1]
670→	}
671→	return len(allLines)
672→}
673→
674→// extractUserPrompts extracts all user prompts from transcript content.
675→// Returns prompts with IDE context tags stripped (e.g., <ide_opened_file>).
676→func extractUserPrompts(agentType types.AgentType, content string) []string {
677→	if content == "" {
678→		return nil
679→	}
680→
681→	// Droid has its own envelope format — use its parser to normalize first
682→	if agentType == agent.AgentTypeFactoryAIDroid {
683→		lines, _, err := factoryaidroid.ParseDroidTranscriptFromBytes([]byte(content), 0)
684→		if err != nil {
685→			return nil
686→		}
687→		var prompts []string
688→		for _, line := range lines {
689→			if line.Type != transcript.TypeUser {
690→				continue
691→			}
692→			if text := transcript.ExtractUserContent(line.Message); text != "" {
693→				if stripped := textutil.StripIDEContextTags(text); stripped != "" {
694→					prompts = append(prompts, stripped)
695→				}
696→			}
697→		}
698→		return prompts
699→	}
700→
701→	// OpenCode uses JSONL with a different per-line schema than Claude Code
702→	if agentType == agent.AgentTypeOpenCode {
703→		prompts, err := opencode.ExtractAllUserPrompts([]byte(content))
704→		if err == nil && len(prompts) > 0 {
705→			cleaned := make([]string, 0, len(prompts))
706→			for _, prompt := range prompts {
707→				if stripped := textutil.StripIDEContextTags(prompt); stripped != "" {
708→					cleaned = append(cleaned, stripped)
709→				}
710→			}
711→			return cleaned
712→		}
713→		return nil
714→	}
715→
716→	// Try Gemini format first if agentType is Gemini, or as fallback if Unknown
717→	if agentType == agent.AgentTypeGemini || agentType == agent.AgentTypeUnknown {
718→		prompts, err := geminicli.ExtractAllUserPrompts([]byte(content))
719→		if err == nil && len(prompts) > 0 {
720→			// Strip IDE context tags for consistency with Claude Code handling
721→			cleaned := make([]string, 0, len(prompts))
722→			for _, prompt := range prompts {
723→				if stripped := textutil.StripIDEContextTags(prompt); stripped != "" {
724→					cleaned = append(cleaned, stripped)
725→				}
726→			}
727→			return cleaned
728→		}
729→		// If agentType is explicitly Gemini but parsing failed, return nil
730→		if agentType == agent.AgentTypeGemini {
731→			return nil
732→		}
733→		// Otherwise fall through to JSONL parsing for Unknown type
734→	}
735→
736→	// Claude Code and other JSONL-based agents
737→	return extractUserPromptsFromLines(strings.Split(content, "\n"))
738→}
739→
740→// extractUserPromptsFromLines extracts user prompts from JSONL transcript lines.
741→// IDE-injected context tags (like <ide_opened_file>) are stripped from the results.
742→func extractUserPromptsFromLines(lines []string) []string {
743→	var prompts []string
744→	for _, line := range lines {
745→		line = strings.TrimSpace(line)
746→		if line == "" {
747→			continue
748→		}
749→
750→		var entry map[string]interface{}
751→		if err := json.Unmarshal([]byte(line), &entry); err != nil {
752→			continue
753→		}
754→
755→		// Check for user message:
756→		// - Claude Code uses "type": "human" or "type": "user"
757→		// - Cursor uses "role": "user"
758→		msgType, _ := entry["type"].(string) //nolint:errcheck // type assertion on interface{} from JSON
759→		msgRole, _ := entry["role"].(string) //nolint:errcheck // type assertion on interface{} from JSON
760→		isUser := msgType == "human" || msgType == "user" || msgRole == "user"
761→		if !isUser {
762→			continue
763→		}
764→
765→		// Extract message content
766→		message, ok := entry["message"].(map[string]interface{})
767→		if !ok {
768→			continue
769→		}
770→
771→		// Handle string content
772→		if content, ok := message["content"].(string); ok && content != "" {
773→			cleaned := textutil.StripIDEContextTags(content)
774→			if cleaned != "" {
775→				prompts = append(prompts, cleaned)
776→			}
777→			continue
778→		}
779→
780→		// Handle array content (e.g., multiple text blocks from VSCode)
781→		if arr, ok := message["content"].([]interface{}); ok {
782→			var texts []string
783→			for _, item := range arr {
784→				if m, ok := item.(map[string]interface{}); ok {
785→					if m["type"] == "text" {
786→						if text, ok := m["text"].(string); ok {
787→							texts = append(texts, text)
788→						}
789→					}
790→				}
791→			}
792→			if len(texts) > 0 {
793→				cleaned := textutil.StripIDEContextTags(strings.Join(texts, "\n\n"))
794→				if cleaned != "" {
795→					prompts = append(prompts, cleaned)
796→				}
797→			}
798→		}
799→	}
800→	return prompts
801→}
802→
803→// splitPromptContent splits prompt.txt content on the "\n\n---\n\n" separator.
804→// Returns nil if content is empty.
805→func splitPromptContent(content string) []string {
806→	if content == "" {
807→		return nil
808→	}
809→	parts := strings.Split(content, "\n\n---\n\n")
810→	var result []string
811→	for _, p := range parts {
812→		trimmed := strings.TrimSpace(p)
813→		if trimmed != "" {
814→			result = append(result, trimmed)
815→		}
816→	}
817→	return result
818→}
