820→// readPromptsFromFilesystem reads prompt.txt from the filesystem session metadata directory.
821→// This file is written at turn start and updated at each SaveStep, providing prompt data
822→// even for mid-turn commits where the shadow branch may not have been updated.
823→func readPromptsFromFilesystem(ctx context.Context, sessionID string) []string {
824→	sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
825→	sessionDirAbs, err := paths.AbsPath(ctx, sessionDir)
826→	if err != nil {
827→		return nil
828→	}
829→	data, err := os.ReadFile(filepath.Join(sessionDirAbs, paths.PromptFileName)) //nolint:gosec // path from session ID
830→	if err != nil || len(data) == 0 {
831→		return nil
832→	}
833→	return splitPromptContent(string(data))
834→}
