931→// cleanupShadowBranchIfUnused deletes a shadow branch if no other active sessions reference it.
932→func (s *ManualCommitStrategy) cleanupShadowBranchIfUnused(ctx context.Context, _ *git.Repository, shadowBranchName, excludeSessionID string) error {
933→	// List all session states to check if any other session uses this shadow branch
934→	allStates, err := s.listAllSessionStates(ctx)
935→	if err != nil {
936→		return fmt.Errorf("failed to list session states: %w", err)
937→	}
938→
939→	for _, state := range allStates {
940→		if state.SessionID == excludeSessionID {
941→			continue
942→		}
943→		otherShadow := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
944→		if otherShadow == shadowBranchName && state.StepCount > 0 {
945→			// Another session still needs this shadow branch
946→			return nil
947→		}
948→	}
949→
950→	// No other sessions need it, delete the shadow branch via CLI
951→	// (go-git v5's RemoveReference doesn't persist with packed refs/worktrees)
952→	if err := DeleteBranchCLI(ctx, shadowBranchName); err != nil {
953→		// Branch already gone is not an error
954→		if errors.Is(err, ErrBranchNotFound) {
955→			return nil
956→		}
957→		return fmt.Errorf("failed to remove shadow branch: %w", err)
958→	}
959→	return nil
960→}
