// buildPrompt constructs the prompt for the Claude CLI.
// All untrusted content (friction text, learnings, context file content) is wrapped
// in XML tags to prevent prompt injection.
func buildPrompt(analysis PatternAnalysis, contextFiles []ContextFile) string {
	var sb strings.Builder

	sb.WriteString(`Analyze recurring patterns from recent AI coding sessions and suggest
improvements to the project's context files.

`)

	// Repeated friction section
	sb.WriteString("<repeated_friction>\n")
	if len(analysis.RepeatedFriction) == 0 {
		sb.WriteString("(no repeated friction patterns found)\n")
	} else {
		for _, p := range analysis.RepeatedFriction {
			fmt.Fprintf(&sb, "Theme: %s issues (occurred %d times)\n", p.Theme, p.Count)
			for _, ex := range p.Examples {
				fmt.Fprintf(&sb, "  - %q\n", ex)
			}
			if p.TranscriptExcerpt != "" {
				fmt.Fprintf(&sb, "  Excerpt: %q\n", p.TranscriptExcerpt)
			}
		}
	}
	sb.WriteString("</repeated_friction>\n\n")

	// Transcript excerpts section
	sb.WriteString("<transcript_excerpts>\n")
	hasExcerpts := false
	for _, p := range analysis.RepeatedFriction {
		if p.TranscriptExcerpt != "" {
			hasExcerpts = true
			break
		}
	}
	if !hasExcerpts {
		sb.WriteString("(transcript excerpts go here when available — may be empty for dry-run)\n")
	}
	sb.WriteString("</transcript_excerpts>\n\n")

	// Learnings section
	sb.WriteString("<learnings>\n")
	for _, l := range analysis.RepoLearnings {
		fmt.Fprintf(&sb, "Repo: %s\n", l)
	}
	for _, l := range analysis.WorkflowLearnings {
		fmt.Fprintf(&sb, "Workflow: %s\n", l)
	}
	if len(analysis.RepoLearnings) == 0 && len(analysis.WorkflowLearnings) == 0 {
		sb.WriteString("(no learnings recorded)\n")
	}
	sb.WriteString("</learnings>\n\n")

	// Current context files section
	sb.WriteString("<current_context_files>\n")
	for _, cf := range contextFiles {
		if cf.Exists {
			fmt.Fprintf(&sb, "--- %s (%d bytes) ---\n", cf.Type, cf.SizeBytes)
			sb.WriteString(cf.Content)
			sb.WriteString("\n--- end ---\n\n")
		} else {
			fmt.Fprintf(&sb, "--- %s (does not exist) ---\n\n", cf.Type)
		}
	}
	if len(contextFiles) == 0 {
		sb.WriteString("(no context files provided)\n")
	}
	sb.WriteString("</current_context_files>\n\n")

	sb.WriteString(`Return a JSON object with this structure:
{
  "suggestions": [{
    "file_type": "CLAUDE.md",
    "category": "fix_friction|add_rule|add_pattern",
    "title": "Short title",
    "description": "Why this helps",
    "evidence": ["friction quote 1"],
    "priority": "high|medium|low",
    "diff": "unified diff"
  }]
}

Guidelines:
- Focus on REPEATED friction (2+ occurrences)
- Include learnings NOT already in context files
- Each suggestion must have a unified diff
- Priority: high for 3+ occurrences, medium for 2, low for learnings
- Do NOT remove existing content unless it contradicts patterns
`)

	return sb.String()
}

package improve

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/llmcli"
)

// Generator generates improvement suggestions using the Claude CLI.
type Generator struct {
	// Runner is the shared Claude CLI execution runner.
	Runner *llmcli.Runner
}

// suggestionResponse is the expected JSON structure returned by the Claude CLI.
type suggestionResponse struct {
	Suggestions []suggestionJSON `json:"suggestions"`
}

// suggestionJSON is the per-suggestion JSON structure in the Claude CLI response.
type suggestionJSON struct {
	FileType    ContextFileType `json:"file_type"`
	Category    string          `json:"category"`
	Title       string          `json:"title"`
	Description string          `json:"description"`
	Evidence    []string        `json:"evidence"`
	Priority    string          `json:"priority"`
	Diff        string          `json:"diff"`
}

// Generate produces context file improvement suggestions.
// analysis contains friction patterns and transcript excerpts.
// contextFiles contains the current context file contents.
func (g *Generator) Generate(ctx context.Context, analysis PatternAnalysis, contextFiles []ContextFile) ([]Suggestion, error) {
	prompt := buildPrompt(analysis, contextFiles)

	raw, err := g.Runner.Execute(ctx, prompt)
	if err != nil {
		return nil, fmt.Errorf("failed to execute improvement prompt: %w", err)
	}

	var resp suggestionResponse
	if err := json.Unmarshal([]byte(raw), &resp); err != nil {
		return nil, fmt.Errorf("failed to parse improvement suggestions: %w", err)
	}

	now := time.Now()
	suggestions := make([]Suggestion, 0, len(resp.Suggestions))
	for i, s := range resp.Suggestions {
		suggestions = append(suggestions, Suggestion{
			ID:          fmt.Sprintf("sug-%d-%d", now.Unix(), i),
			FileType:    s.FileType,
			Category:    s.Category,
			Title:       s.Title,
			Description: s.Description,
			Evidence:    s.Evidence,
			Priority:    s.Priority,
			Diff:        s.Diff,
			CreatedAt:   now,
			Status:      "pending",
		})
	}

	return suggestions, nil
}

// Package llmcli provides a shared runner for executing prompts via the Claude CLI.
package llmcli

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"
)

// DefaultModel is the default Claude model used when Model is not set.
// Sonnet provides a good balance of quality and cost, with 1M context window
// to handle long transcripts without truncation.
const DefaultModel = "sonnet"

// Runner executes prompts via the Claude CLI.
type Runner struct {
	// ClaudePath is the path to the claude CLI executable.
	// If empty, defaults to "claude".
	ClaudePath string

	// Model is the Claude model to use.
	// If empty, defaults to DefaultModel ("sonnet").
	Model string

	// CommandRunner allows injection of the command execution for testing.
	// If nil, uses exec.CommandContext directly.
	CommandRunner func(ctx context.Context, name string, args ...string) *exec.Cmd
}

// claudeCLIResponse represents the JSON response from the Claude CLI.
type claudeCLIResponse struct {
	Result string `json:"result"`
}

// Execute runs a prompt through the Claude CLI and returns the raw text result.
//
// It handles:
//   - CLI invocation with --print --output-format json --model --setting-sources ""
//   - Git isolation (TempDir cwd, strip GIT_* env vars)
//   - Response parsing ({"result": "string"} format)
//   - Markdown code block extraction from the result field
func (r *Runner) Execute(ctx context.Context, prompt string) (string, error) {
	runner := r.CommandRunner
	if runner == nil {
		runner = exec.CommandContext
	}

	claudePath := r.ClaudePath
	if claudePath == "" {
		claudePath = "claude"
	}

	model := r.Model
	if model == "" {
		model = DefaultModel
	}

	// Use empty --setting-sources to skip all settings (user, project, local).
	// This avoids loading MCP servers, hooks, or other config that could interfere
	// with a simple --print call.
	cmd := runner(ctx, claudePath, "--print", "--output-format", "json", "--model", model, "--setting-sources", "")

	// Fully isolate the subprocess from the user's git repo (ENT-242).
	// Claude Code performs internal git operations (plugin cache, context gathering)
	// that pollute the worktree index with phantom entries from its plugin cache.
	// We must both change the working directory AND strip GIT_* env vars, because
	// git hooks set GIT_DIR which lets Claude Code find the repo regardless of cwd.
	// This also prevents recursive triggering of Entire's own git hooks.
	cmd.Dir = os.TempDir()
	cmd.Env = StripGitEnv(os.Environ())

	cmd.Stdin = strings.NewReader(prompt)

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()
	if err != nil {
		var execErr *exec.Error
		if errors.As(err, &execErr) {
			return "", fmt.Errorf("claude CLI not found: %w", err)
		}

		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			return "", fmt.Errorf("claude CLI failed (exit %d): %s", exitErr.ExitCode(), stderr.String())
		}

		return "", fmt.Errorf("failed to run claude CLI: %w", err)
	}

	var cliResponse claudeCLIResponse
	if err := json.Unmarshal(stdout.Bytes(), &cliResponse); err != nil {
		return "", fmt.Errorf("failed to parse claude CLI response: %w", err)
	}

	// Extract JSON if it's wrapped in markdown code blocks.
	result := ExtractJSONFromMarkdown(cliResponse.Result)

	return result, nil
}

// StripGitEnv returns a copy of env with all GIT_* variables removed.
// This prevents a subprocess from discovering or modifying the parent's git repo.
func StripGitEnv(env []string) []string {
	filtered := make([]string, 0, len(env))
	for _, e := range env {
		if !strings.HasPrefix(e, "GIT_") {
			filtered = append(filtered, e)
		}
	}
	return filtered
}

// ExtractJSONFromMarkdown attempts to extract JSON from markdown code blocks.
// If the input is not wrapped in code blocks, it returns the input unchanged.
func ExtractJSONFromMarkdown(s string) string {
	s = strings.TrimSpace(s)

	// Check for ```json ... ``` blocks
	if strings.HasPrefix(s, "```json") {
		s = strings.TrimPrefix(s, "```json")
		if idx := strings.LastIndex(s, "```"); idx != -1 {
			s = s[:idx]
		}
		return strings.TrimSpace(s)
	}

	// Check for ``` ... ``` blocks
	if strings.HasPrefix(s, "```") {
		s = strings.TrimPrefix(s, "```")
		if idx := strings.LastIndex(s, "```"); idx != -1 {
			s = s[:idx]
		}
		return strings.TrimSpace(s)
	}

	return s
}

