func TestStripGitEnv(t *testing.T) {
	t.Parallel()

	env := []string{
		"HOME=/Users/test",
		"GIT_DIR=/repo/.git",
		"PATH=/usr/bin",
		"GIT_WORK_TREE=/repo",
		"GIT_INDEX_FILE=/repo/.git/index",
		"SHELL=/bin/zsh",
	}

	filtered := llmcli.StripGitEnv(env)

	expected := []string{
		"HOME=/Users/test",
		"PATH=/usr/bin",
		"SHELL=/bin/zsh",
	}

	if len(filtered) != len(expected) {
		t.Fatalf("got %d entries, want %d", len(filtered), len(expected))
	}

	for i, e := range filtered {
		if e != expected[i] {
			t.Errorf("filtered[%d] = %q, want %q", i, e, expected[i])
		}
	}
}

func TestStripGitEnv_Empty(t *testing.T) {
	t.Parallel()

	result := llmcli.StripGitEnv([]string{})
	if len(result) != 0 {
		t.Errorf("expected empty slice, got %v", result)
	}
}

func TestStripGitEnv_NoGitVars(t *testing.T) {
	t.Parallel()

	env := []string{"HOME=/Users/test", "PATH=/usr/bin"}
	result := llmcli.StripGitEnv(env)
	if len(result) != 2 {
		t.Errorf("expected 2 entries, got %d", len(result))
	}
}

func TestExtractJSONFromMarkdown(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name     string
		input    string
		expected string
	}{
		{
			name:     "plain JSON",
			input:    `{"key": "value"}`,
			expected: `{"key": "value"}`,
		},
		{
			name:     "json code block",
			input:    "```json\n{\"key\": \"value\"}\n```",
			expected: `{"key": "value"}`,
		},
		{
			name:     "plain code block",
			input:    "```\n{\"key\": \"value\"}\n```",
			expected: `{"key": "value"}`,
		},
		{
			name:     "with whitespace",
			input:    "  \n```json\n{\"key\": \"value\"}\n```  \n",
			expected: `{"key": "value"}`,
		},
		{
			name:     "unclosed block",
			input:    "```json\n{\"key\": \"value\"}",
			expected: `{"key": "value"}`,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			result := llmcli.ExtractJSONFromMarkdown(tt.input)
			if result != tt.expected {
				t.Errorf("expected %q, got %q", tt.expected, result)
			}
		})
	}
}

