 1→package insights
 2→
 3→import (
 4→	"math"
 5→)
 6→
 7→// Weights for composite score.
 8→const (
 9→	WeightTokenEfficiency  = 0.30
10→	WeightFirstPassSuccess = 0.30
11→	WeightFriction         = 0.25
12→	WeightFocus            = 0.15
13→)
14→
15→// ScoreSession computes a score breakdown from session data.
16→// This is a pure function — no I/O.
17→// The Overall score is NOT computed here — call ComputeOverall with the result.
18→func ScoreSession(data SessionData) ScoreBreakdown {
19→	return ScoreBreakdown{
20→		TokenEfficiency:  scoreTokenEfficiency(data),
21→		FirstPassSuccess: scoreFirstPassSuccess(data),
22→		FrictionScore:    scoreFriction(data),
23→		FocusScore:       scoreFocus(data),
24→	}
25→}
26→
27→// ComputeOverall applies weights to a breakdown and returns the composite 0-100 score
28→// rounded to 1 decimal place.
29→func ComputeOverall(b ScoreBreakdown) float64 {
30→	raw := b.TokenEfficiency*WeightTokenEfficiency +
31→		b.FirstPassSuccess*WeightFirstPassSuccess +
32→		b.FrictionScore*WeightFriction +
33→		b.FocusScore*WeightFocus
34→	return math.Round(raw*10) / 10
35→}
36→
37→// clampScore clamps s to the range [0, 100].
38→func clampScore(s float64) float64 {
39→	if s < 0 {
40→		return 0
41→	}
42→	if s > 100 {
43→		return 100
44→	}
45→	return s
46→}
47→
48→// scoreTokenEfficiency returns 100*exp(-tokensPerFile/8000).
49→// Returns 50 (neutral) when filesCount==0 or totalTokens==0.
50→func scoreTokenEfficiency(data SessionData) float64 {
51→	if data.FilesCount == 0 || data.TotalTokens == 0 {
52→		return 50
53→	}
54→	tokensPerFile := float64(data.TotalTokens) / float64(data.FilesCount)
55→	return 100 * math.Exp(-tokensPerFile/8000)
56→}
57→
58→// scoreFirstPassSuccess returns a score starting at 80, deducting for friction,
59→// extra turns, and open items. Returns 50 (neutral) when HasSummary is false.
60→func scoreFirstPassSuccess(data SessionData) float64 {
61→	if !data.HasSummary {
62→		return 50
63→	}
64→	score := 80.0
65→	score -= float64(data.FrictionCount) * 10
66→	if data.TurnCount > 5 {
67→		score -= float64(data.TurnCount-5) * 3
68→	}
69→	score -= float64(data.OpenItemCount) * 5
70→	return clampScore(score)
71→}
72→
73→// scoreFriction returns 100 - frictionCount*20, clamped to [0,100].
74→func scoreFriction(data SessionData) float64 {
75→	return clampScore(100 - float64(data.FrictionCount)*20)
76→}
77→
78→// scoreFocus returns a score based on the file-to-turn ratio.
79→// Returns 50 (neutral) when turns==0 or files==0.
80→func scoreFocus(data SessionData) float64 {
81→	if data.TurnCount == 0 || data.FilesCount == 0 {
82→		return 50
83→	}
84→	ratio := float64(data.FilesCount) / float64(data.TurnCount)
85→	var score float64
86→	switch {
87→	case ratio >= 0.5 && ratio <= 3.0:
88→		score = 90
89→	case ratio < 0.5:
90→		score = 50 + ratio*80
91→	default: // ratio > 3.0
92→		score = 90 - (ratio-3.0)*10
93→	}
94→	return clampScore(score)
95→}
96→

