 24→func newImproveCmd() *cobra.Command {
 25→	var last int
 26→	var dryRun bool
 27→	var outputJSON bool
 28→
 29→	cmd := &cobra.Command{
 30→		Use:   "improve",
 31→		Short: "Suggest improvements to project context files based on session patterns",
 32→		RunE: func(cmd *cobra.Command, _ []string) error {
 33→			ctx := cmd.Context()
 34→			w := cmd.OutOrStdout()
 35→
 36→			if checkDisabledGuard(ctx, w) {
 37→				return nil
 38→			}
 39→
 40→			if !settings.IsSummarizeEnabled(ctx) {
 41→				fmt.Fprintln(w, "Summarization is required for improve. Enable it in .entire/settings.json:")
 42→				fmt.Fprintln(w, `  { "strategy_options": { "summarize": { "enabled": true } } }`)
 43→				return nil
 44→			}
 45→
 46→			return runImprove(ctx, w, last, dryRun, outputJSON)
 47→		},
 48→	}
 49→
 50→	cmd.Flags().IntVar(&last, "last", 10, "number of recent sessions to analyze")
 51→	cmd.Flags().BoolVar(&dryRun, "dry-run", false, "show friction patterns only, no AI call, no transcript read")
 52→	cmd.Flags().BoolVar(&outputJSON, "json", false, "output as JSON instead of styled terminal output")
 53→
 54→	return cmd
