141→// buildFrictionPatterns converts insightsdb friction themes to improve.FrictionPattern values.
142→func buildFrictionPatterns(themes []insightsdb.FrictionTheme) []improve.FrictionPattern {
143→	patterns := make([]improve.FrictionPattern, 0, len(themes))
144→	for _, t := range themes {
145→		patterns = append(patterns, improve.FrictionPattern{
146→			Theme:            t.Text,
147→			Count:            t.Count,
148→			AffectedSessions: t.Sessions,
149→		})
150→	}
151→	return patterns
152→}
