154→// attachTranscriptExcerpts fetches transcript excerpts for top friction themes and
155→// attaches them to the corresponding patterns in-place.
156→// Errors are non-fatal; unreadable sessions are silently skipped.
157→func attachTranscriptExcerpts(ctx context.Context, idb *insightsdb.InsightsDB, patterns []improve.FrictionPattern, _ string) error {
158→	repo, err := openRepository(ctx)
159→	if err != nil {
160→		return fmt.Errorf("open git repository: %w", err)
161→	}
162→	store := checkpoint.NewGitStore(repo)
163→
164→	// Limit to top 3 friction themes.
165→	limit := 3
166→	if len(patterns) < limit {
167→		limit = len(patterns)
168→	}
169→
170→	for i := range patterns[:limit] {
171→		cpIDs, queryErr := idb.QuerySessionsWithFriction(ctx, "%"+patterns[i].Theme+"%")
172→		if queryErr != nil {
173→			continue
174→		}
175→
176→		// Limit to top 2 sessions per theme.
177→		sessionLimit := 2
178→		if len(cpIDs) < sessionLimit {
179→			sessionLimit = len(cpIDs)
180→		}
181→
182→		var excerpts []string
183→		for _, cpIDStr := range cpIDs[:sessionLimit] {
184→			cpID, parseErr := checkpointid.NewCheckpointID(cpIDStr)
185→			if parseErr != nil {
186→				continue
187→			}
188→
189→			content, readErr := store.ReadSessionContent(ctx, cpID, 0)
190→			if readErr != nil {
191→				continue
192→			}
193→
194→			condensed, buildErr := summarize.BuildCondensedTranscriptFromBytes(content.Transcript, content.Metadata.Agent)
195→			if buildErr != nil || len(condensed) == 0 {
196→				continue
197→			}
198→
199→			formatted := summarize.FormatCondensedTranscript(summarize.Input{Transcript: condensed})
200→			excerpt := truncateString(formatted, 2000)
201→			if excerpt != "" {
202→				excerpts = append(excerpts, excerpt)
203→			}
204→		}
205→
206→		if len(excerpts) > 0 {
207→			patterns[i].TranscriptExcerpt = strings.Join(excerpts, "\n---\n")
208→		}
209→	}
210→
211→	return nil
212→}
213→
214→// applyExcerpts copies TranscriptExcerpt values from src patterns into dst patterns
215→// by matching on theme text.
216→func applyExcerpts(dst []improve.FrictionPattern, src []improve.FrictionPattern) {
217→	excerptByTheme := make(map[string]string, len(src))
218→	for _, p := range src {
219→		if p.TranscriptExcerpt != "" {
220→			excerptByTheme[p.Theme] = p.TranscriptExcerpt
221→		}
222→	}
223→	for i := range dst {
224→		if excerpt, ok := excerptByTheme[dst[i].Theme]; ok {
225→			dst[i].TranscriptExcerpt = excerpt
226→		}
227→	}
228→}
