230→// sessionRowsToSummaries converts insightsdb rows into improve.SessionSummaryData values.
231→func sessionRowsToSummaries(rows []insightsdb.SessionRow) []improve.SessionSummaryData {
232→	summaries := make([]improve.SessionSummaryData, 0, len(rows))
233→	for _, r := range rows {
234→		s := improve.SessionSummaryData{
235→			CheckpointID: r.CheckpointID,
236→			Friction:     r.Friction,
237→		}
238→		for _, l := range r.Learnings {
239→			s.Learnings = append(s.Learnings, improve.LearningEntry{
240→				Scope:   l.Scope,
241→				Finding: l.Finding,
242→				Path:    l.Path,
243→			})
244→		}
245→		summaries = append(summaries, s)
246→	}
247→	return summaries
248→}
