285→// renderImproveTerminal writes a styled terminal view of the improvement report.
286→func renderImproveTerminal(w io.Writer, report improve.ImprovementReport) {
287→	s := termstyle.New(w)
288→
289→	fmt.Fprintln(w, s.Render(s.Bold, "Entire Improve"))
290→	fmt.Fprintf(w, "Analyzed %d sessions | %d friction points | %d patterns found\n\n",
291→		report.SessionsUsed, report.FrictionTotal, report.PatternsFound)
292→
293→	// Context Files section.
294→	fmt.Fprintln(w, s.SectionRule("Context Files"))
295→	for _, cf := range report.ContextFiles {
296→		if cf.Exists {
297→			line := fmt.Sprintf("  %s  %d bytes", cf.Type, cf.SizeBytes)
298→			fmt.Fprintln(w, s.Render(s.Bold, line))
299→		} else {
300→			line := fmt.Sprintf("  %s  missing", cf.Type)
301→			fmt.Fprintln(w, s.Render(s.Gray, line))
302→		}
303→	}
304→	fmt.Fprintln(w)
305→
306→	// Suggestions section.
307→	fmt.Fprintln(w, s.SectionRule(fmt.Sprintf("Suggestions (%d)", len(report.Suggestions))))
308→	if len(report.Suggestions) == 0 {
309→		fmt.Fprintln(w, "  No suggestions generated.")
310→	}
311→	for i, sug := range report.Suggestions {
312→		// Title line with priority.
313→		titleLine := fmt.Sprintf("  %d. %s  %s", i+1, sug.Title, sug.Priority)
314→		fmt.Fprintln(w, s.Render(s.Bold, titleLine))
315→
316→		// Category and file.
317→		metaLine := fmt.Sprintf("     %s → %s", sug.Category, sug.FileType)
318→		fmt.Fprintln(w, s.Render(s.Dim, metaLine))
319→
320→		// Description.
321→		if sug.Description != "" {
322→			fmt.Fprintf(w, "     %s\n", sug.Description)
323→		}
324→
325→		// Diff rendering.
326→		if sug.Diff != "" {
327→			fmt.Fprintln(w)
328→			renderDiff(w, s, sug.Diff)
329→		}
330→		fmt.Fprintln(w)
331→	}
332→}
