364→// renderDiff writes a unified diff with colored lines to w.
365→// Lines starting with '+' are rendered in green, '-' in red, '@@' in cyan,
366→// and all other lines in dim.
367→func renderDiff(w io.Writer, s termstyle.Styles, diff string) {
368→	for _, line := range strings.Split(diff, "\n") {
369→		switch {
370→		case strings.HasPrefix(line, "@@"):
371→			fmt.Fprintln(w, s.Render(s.Cyan, line))
372→		case strings.HasPrefix(line, "+"):
373→			fmt.Fprintln(w, s.Render(s.Green, line))
374→		case strings.HasPrefix(line, "-"):
375→			fmt.Fprintln(w, s.Render(s.Red, line))
376→		default:
377→			fmt.Fprintln(w, s.Render(s.Dim, line))
378→		}
379→	}
380→}
