		fmt.Fprintln(w, s.Render(s.Gray, statsLine))

		if ac.TopStrength != "" {
			fmt.Fprintln(w, s.Render(s.Green, "  + "+ac.TopStrength))
		}
		if ac.TopWeakness != "" {
