 23→	OutputTokens int
 24→	TotalTokens  int
 25→	APICallCount int
 26→	DurationMs   int64
 27→	TurnCount    int
 28→	Intent       string
 29→	Outcome      string
 30→	AgentPct     float64
 31→	// Score fields
 32→	OverallScore   float64
 33→	ScoreTokenEff  float64
 34→	ScoreFirstPass float64
 35→	ScoreFriction  float64
 36→	ScoreFocus     float64
 37→	HasSummary     bool
 38→	// Denormalized arrays
 39→	FilesTouched []string
