 49→}
 50→
 51→// GetBranchTip returns the stored branch tip hash from cache_meta,
 52→// or an empty string if it has not been set yet.
 53→func (idb *InsightsDB) GetBranchTip(ctx context.Context) (string, error) {
 54→	var tip string
 55→	err := idb.db.QueryRowContext(ctx,
 56→		"SELECT value FROM cache_meta WHERE key = ?",
 57→		"branch_tip",
 58→	).Scan(&tip)
 59→	if err == sql.ErrNoRows {
 60→		return "", nil
 61→	}
 62→	if err != nil {
 63→		return "", fmt.Errorf("get branch tip: %w", err)
 64→	}
 65→	return tip, nil
 66→}
 67→
 68→// SetBranchTip stores the branch tip hash in cache_meta.
 69→// Overwrites any previously stored value.
 70→func (idb *InsightsDB) SetBranchTip(ctx context.Context, tip string) error {
 71→	_, err := idb.db.ExecContext(ctx,
 72→		"INSERT OR REPLACE INTO cache_meta (key, value) VALUES (?, ?)",
 73→		"branch_tip",
 74→		tip,
 75→	)
 76→	if err != nil {
 77→		return fmt.Errorf("set branch tip: %w", err)
 78→	}
 79→	return nil
 80→}
 81→
 82→// HasCheckpoint returns true if any session for the given checkpoint ID
 83→// is already present in the sessions table.
 84→func (idb *InsightsDB) HasCheckpoint(ctx context.Context, checkpointID string) (bool, error) {
 85→	var count int
 86→	err := idb.db.QueryRowContext(ctx,
 87→		"SELECT COUNT(*) FROM sessions WHERE checkpoint_id = ?",
 88→		checkpointID,
 89→	).Scan(&count)
 90→	if err != nil {
 91→		return false, fmt.Errorf("check checkpoint existence: %w", err)
 92→	}
 93→	return count > 0, nil
 94→}
