129→func insertSessionRow(ctx context.Context, tx *sql.Tx, row SessionRow) error {
130→	hasSummary := 0
131→	if row.HasSummary {
132→		hasSummary = 1
133→	}
134→	_, err := tx.ExecContext(ctx, `
135→		INSERT INTO sessions (
136→			checkpoint_id, session_id, session_index,
137→			agent, model, branch, created_at,
138→			input_tokens, cache_tokens, output_tokens, total_tokens,
139→			api_call_count, duration_ms, turn_count,
140→			intent, outcome, agent_percentage,
141→			overall_score, score_token_efficiency, score_first_pass,
142→			score_friction, score_focus, has_summary
143→		) VALUES (
144→			?, ?, ?,
145→			?, ?, ?, ?,
146→			?, ?, ?, ?,
147→			?, ?, ?,
148→			?, ?, ?,
149→			?, ?, ?,
150→			?, ?, ?
151→		)`,
152→		row.CheckpointID, row.SessionID, row.SessionIndex,
153→		nullableString(row.Agent), nullableString(row.Model), nullableString(row.Branch),
154→		row.CreatedAt.UTC().Format(time.RFC3339),
155→		row.InputTokens, row.CacheTokens, row.OutputTokens, row.TotalTokens,
156→		row.APICallCount, row.DurationMs, row.TurnCount,
157→		nullableString(row.Intent), nullableString(row.Outcome), row.AgentPct,
158→		row.OverallScore, row.ScoreTokenEff,
159→		row.ScoreFirstPass, row.ScoreFriction,
160→		row.ScoreFocus, hasSummary,
161→	)
162→	if err != nil {
163→		return fmt.Errorf("insert session row: %w", err)
164→	}
165→	return nil
166→}
167→
168→func insertFilesTouched(ctx context.Context, tx *sql.Tx, row SessionRow) error {
169→	for _, f := range row.FilesTouched {
170→		if _, err := tx.ExecContext(ctx,
171→			"INSERT INTO files_touched (checkpoint_id, session_index, file_path) VALUES (?, ?, ?)",
172→			row.CheckpointID, row.SessionIndex, f,
173→		); err != nil {
174→			return fmt.Errorf("insert files_touched: %w", err)
175→		}
176→	}
177→	return nil
178→}
179→
180→func insertFriction(ctx context.Context, tx *sql.Tx, row SessionRow) error {
181→	for _, f := range row.Friction {
182→		if _, err := tx.ExecContext(ctx,
183→			"INSERT INTO friction (checkpoint_id, session_index, text) VALUES (?, ?, ?)",
184→			row.CheckpointID, row.SessionIndex, f,
185→		); err != nil {
186→			return fmt.Errorf("insert friction: %w", err)
187→		}
188→	}
189→	return nil
190→}
191→
192→func insertLearnings(ctx context.Context, tx *sql.Tx, row SessionRow) error {
193→	for _, l := range row.Learnings {
194→		if _, err := tx.ExecContext(ctx,
195→			"INSERT INTO learnings (checkpoint_id, session_index, scope, finding, path) VALUES (?, ?, ?, ?, ?)",
196→			row.CheckpointID, row.SessionIndex, l.Scope, l.Finding, nullableString(l.Path),
197→		); err != nil {
198→			return fmt.Errorf("insert learnings: %w", err)
199→		}
200→	}
201→	return nil
202→}
203→
204→// UpdateSessionSummary updates an existing session row with summary-derived data
205→// (intent, outcome, scores, friction, learnings) and sets has_summary = 1.
206→func (idb *InsightsDB) UpdateSessionSummary(ctx context.Context, row SessionRow) error {
207→	tx, err := idb.db.BeginTx(ctx, nil)
208→	if err != nil {
209→		return fmt.Errorf("begin transaction: %w", err)
210→	}
211→	defer func() {
212→		if err != nil {
213→			_ = tx.Rollback() //nolint:errcheck // Rollback after failed tx; error is irrelevant
214→		}
215→	}()
216→
217→	_, err = tx.ExecContext(ctx, `
218→		UPDATE sessions SET
219→			intent = ?, outcome = ?,
220→			overall_score = ?, score_token_efficiency = ?, score_first_pass = ?,
221→			score_friction = ?, score_focus = ?, has_summary = 1
222→		WHERE checkpoint_id = ? AND session_index = ?`,
223→		nullableString(row.Intent), nullableString(row.Outcome),
224→		row.OverallScore, row.ScoreTokenEff, row.ScoreFirstPass,
225→		row.ScoreFriction, row.ScoreFocus,
226→		row.CheckpointID, row.SessionIndex,
227→	)
228→	if err != nil {
229→		return fmt.Errorf("update session summary: %w", err)
230→	}
231→
232→	// Delete old friction/learnings and re-insert.
233→	for _, table := range []string{"friction", "learnings"} {
234→		if _, err = tx.ExecContext(ctx,
235→			"DELETE FROM "+table+" WHERE checkpoint_id = ? AND session_index = ?", //nolint:gosec // table name is hardcoded
236→			row.CheckpointID, row.SessionIndex,
237→		); err != nil {
238→			return fmt.Errorf("delete old %s: %w", table, err)
239→		}
240→	}
241→
242→	if err = insertFriction(ctx, tx, row); err != nil {
243→		return err
244→	}
245→	if err = insertLearnings(ctx, tx, row); err != nil {
246→		return err
247→	}
248→
249→	if err = tx.Commit(); err != nil {
250→		return fmt.Errorf("commit transaction: %w", err)
251→	}
252→	return nil
253→}
