			}
			if got.FirstPassSuccess < tt.wantMin || got.FirstPassSuccess > tt.wantMax {
				t.Errorf("FirstPassSuccess = %v, want [%v, %v]", got.FirstPassSuccess, tt.wantMin, tt.wantMax)
			}
		})
	}
}

