		{"five friction is 0", SessionData{FrictionCount: 5}, 0.0},
		{"six friction clamped to 0", SessionData{FrictionCount: 6}, 0.0},
		{"ten friction clamped to 0", SessionData{FrictionCount: 10}, 0.0},
	}

	for _, tt := range tests {
