	tests := []struct {
		name string
		b    ScoreBreakdown
		want float64
	}{
		{
			name: "all 100 gives 100",
			b:    ScoreBreakdown{TokenEfficiency: 100, FirstPassSuccess: 100, FrictionScore: 100, FocusScore: 100},
