  5→// maxFrictionExamples caps the number of raw examples stored per friction theme
  6→// to prevent unbounded growth in LLM prompts.
  7→const maxFrictionExamples = 10
  8→
  9→// SessionSummaryData pairs a session identifier with its friction and learnings.
 10→// This is populated from the insightsdb cache.
 11→type SessionSummaryData struct {
 12→	CheckpointID string
 13→	Friction     []string
 14→	Learnings    []LearningEntry
 15→	OpenItems    []string
 16→}
 17→
 18→// LearningEntry represents a single learning from a session.
 19→type LearningEntry struct {
 20→	Scope   string // "repo", "workflow", "code"
 21→	Finding string
 22→	Path    string
 23→}
 24→
 25→// frictionThemeKeywords maps theme names to their detection keywords.
 26→// Order matters: first match wins.
 27→var frictionThemeKeywords = []struct {
 28→	theme    string
 29→	keywords []string
 30→}{
 31→	{"lint", []string{"lint", "golangci", "linter"}},
 32→	{"import", []string{"import"}},
 33→	{"compile", []string{"compile", "build error", "compilation"}},
 34→	{"format", []string{"format", "fmt", "gofmt"}},
 35→	{"test", []string{"test", "testing"}},
 36→	{"type", []string{"type assertion", "type error", "type mismatch", "type check"}},
 37→	{"permission", []string{"permission", "denied", "unauthorized"}},
 38→	{"timeout", []string{"timeout", "timed out"}},
 39→	{"retry", []string{"retry", "retrying"}},
 40→}
 41→
 42→// classifyFriction returns the theme keyword for a friction string,
 43→// or "other" if no known keyword matches.
 44→func classifyFriction(text string) string {
 45→	lower := strings.ToLower(text)
 46→	for _, entry := range frictionThemeKeywords {
 47→		for _, kw := range entry.keywords {
 48→			if strings.Contains(lower, kw) {
 49→				return entry.theme
 50→			}
 51→		}
 52→	}
 53→	return "other"
 54→}
 55→
 56→// frictionAccumulator accumulates friction examples and affected sessions per theme.
 57→type frictionAccumulator struct {
 58→	count    int
 59→	examples []string
 60→	sessions map[string]struct{} // deduplicated session IDs
 61→}
 62→
 63→// AnalyzePatterns extracts recurring patterns from session summary data.
 64→// This is the "index phase" — it works on data already in memory from SQLite.
 65→func AnalyzePatterns(summaries []SessionSummaryData) PatternAnalysis {
 66→	if len(summaries) == 0 {
 67→		return PatternAnalysis{}
 68→	}
 69→
 70→	// Accumulate friction by theme
 71→	byTheme := make(map[string]*frictionAccumulator)
 72→
 73→	for _, s := range summaries {
 74→		for _, f := range s.Friction {
 75→			theme := classifyFriction(f)
 76→			acc, ok := byTheme[theme]
 77→			if !ok {
 78→				acc = &frictionAccumulator{
 79→					sessions: make(map[string]struct{}),
 80→				}
 81→				byTheme[theme] = acc
 82→			}
 83→			acc.count++
 84→			if len(acc.examples) < maxFrictionExamples {
 85→				acc.examples = append(acc.examples, f)
 86→			}
 87→			if s.CheckpointID != "" {
 88→				acc.sessions[s.CheckpointID] = struct{}{}
 89→			}
 90→		}
 91→	}
 92→
 93→	// Build repeated friction list (threshold: 2+ occurrences)
 94→	var repeated []FrictionPattern
 95→	for theme, acc := range byTheme {
 96→		if acc.count < 2 {
 97→			continue
 98→		}
 99→		sessions := make([]string, 0, len(acc.sessions))
100→		for id := range acc.sessions {
101→			sessions = append(sessions, id)
102→		}
103→		repeated = append(repeated, FrictionPattern{
104→			Theme:            theme,
105→			Count:            acc.count,
106→			Examples:         acc.examples,
107→			AffectedSessions: sessions,
108→		})
109→	}
110→
111→	// Deduplicate learnings by scope
112→	repoSeen := make(map[string]struct{})
113→	workflowSeen := make(map[string]struct{})
114→	var repoLearnings, workflowLearnings []string
115→
116→	for _, s := range summaries {
117→		for _, l := range s.Learnings {
118→			switch l.Scope {
119→			case "repo":
120→				if _, seen := repoSeen[l.Finding]; !seen {
121→					repoSeen[l.Finding] = struct{}{}
122→					repoLearnings = append(repoLearnings, l.Finding)
123→				}
124→			case "workflow":
125→				if _, seen := workflowSeen[l.Finding]; !seen {
126→					workflowSeen[l.Finding] = struct{}{}
127→					workflowLearnings = append(workflowLearnings, l.Finding)
128→				}
129→			}
130→		}
131→	}
132→
133→	// Deduplicate open items
134→	openSeen := make(map[string]struct{})
135→	var openItems []string
136→	for _, s := range summaries {
137→		for _, item := range s.OpenItems {
138→			if _, seen := openSeen[item]; !seen {
139→				openSeen[item] = struct{}{}
140→				openItems = append(openItems, item)
141→			}
142→		}
143→	}
144→
145→	return PatternAnalysis{
146→		RepeatedFriction:  repeated,
147→		RepoLearnings:     repoLearnings,
148→		WorkflowLearnings: workflowLearnings,
149→		OpenItems:         openItems,
150→		SessionCount:      len(summaries),
151→	}
152→}
