 57→// runImprove fetches session data from the SQLite cache, refreshes it if stale,
 58→// then analyzes friction patterns and optionally generates context file improvements.
 59→func runImprove(ctx context.Context, w io.Writer, last int, dryRun bool, outputJSON bool) error {
 60→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 61→	if err != nil {
 62→		return fmt.Errorf("not in a git repository: %w", err)
 63→	}
 64→	entireDir := filepath.Join(worktreeRoot, paths.EntireDir)
 65→
 66→	idb, err := insightsdb.Open(filepath.Join(entireDir, "insights.db"))
 67→	if err != nil {
 68→		return fmt.Errorf("open insights cache: %w", err)
 69→	}
 70→	defer func() { _ = idb.Close() }()
 71→
 72→	// Non-fatal: continue with whatever is in the cache.
 73→	refreshCacheIfStale(ctx, idb) //nolint:errcheck,gosec // Non-fatal; continue with stale cache
 74→
 75→	// Generate summaries for recent sessions that lack them.
 76→	if !dryRun {
 77→		backfillSummaries(ctx, w, idb, last)
 78→	}
 79→
 80→	// Phase 1: Query SQLite index for recurring friction themes (2+ occurrences).
 81→	frictionThemes, err := idb.QueryRecurringFriction(ctx, 2)
 82→	if err != nil {
 83→		return fmt.Errorf("query recurring friction: %w", err)
 84→	}
 85→
 86→	// Fetch the last N sessions for summary stats.
 87→	rows, err := idb.QueryLastNSessions(ctx, last)
 88→	if err != nil {
 89→		return fmt.Errorf("query sessions: %w", err)
 90→	}
 91→
 92→	// Count total friction items across all sessions.
 93→	frictionTotal := 0
 94→	for _, r := range rows {
 95→		frictionTotal += len(r.Friction)
 96→	}
 97→
 98→	if dryRun {
 99→		if outputJSON {
100→			return renderImproveJSONDryRun(w, frictionThemes, len(rows), frictionTotal)
101→		}
102→		renderImproveTerminalDryRun(w, frictionThemes, len(rows), frictionTotal)
103→		return nil
104→	}
105→
106→	// Phase 2: Deep-read transcripts for top friction themes.
107→	patterns := buildFrictionPatterns(frictionThemes)
108→	if err = attachTranscriptExcerpts(ctx, idb, patterns, worktreeRoot); err != nil {
109→		// Non-fatal: proceed without transcript excerpts.
110→		_ = err
111→	}
112→
113→	// Phase 3: Detect context files.
114→	contextFiles := improve.DetectContextFiles(worktreeRoot)
115→
116→	// Phase 4: Build analysis from session data + friction patterns, then generate.
117→	summaries := sessionRowsToSummaries(rows)
118→	analysis := improve.AnalyzePatterns(summaries)
119→	// Overlay the transcript excerpts we fetched into the analysis.
120→	applyExcerpts(analysis.RepeatedFriction, patterns)
121→
122→	gen := improve.Generator{Runner: &llmcli.Runner{}}
123→	result, err := gen.Generate(ctx, analysis, contextFiles)
124→	if err != nil {
125→		return fmt.Errorf("generate suggestions: %w", err)
126→	}
127→
128→	report := improve.ImprovementReport{
129→		ContextFiles:  contextFiles,
130→		Suggestions:   result.Suggestions,
131→		SessionsUsed:  len(rows),
132→		FrictionTotal: frictionTotal,
133→		PatternsFound: len(analysis.RepeatedFriction),
134→	}
135→
136→	if outputJSON {
137→		return renderImproveJSON(w, report)
138→	}
139→	renderImproveTerminal(w, report)
140→	if result.Usage != nil {
141→		renderUsageLine(w, result.Usage)
142→	}
143→	return nil
144→}
