146→// buildFrictionPatterns converts insightsdb friction themes to improve.FrictionPattern values.
147→func buildFrictionPatterns(themes []insightsdb.FrictionTheme) []improve.FrictionPattern {
148→	patterns := make([]improve.FrictionPattern, 0, len(themes))
149→	for _, t := range themes {
150→		patterns = append(patterns, improve.FrictionPattern{
151→			Theme:            t.Text,
152→			Count:            t.Count,
153→			AffectedSessions: t.Sessions,
154→		})
155→	}
156→	return patterns
157→}
