159→// attachTranscriptExcerpts fetches transcript excerpts for top friction themes and
160→// attaches them to the corresponding patterns in-place.
161→// Errors are non-fatal; unreadable sessions are silently skipped.
162→func attachTranscriptExcerpts(ctx context.Context, idb *insightsdb.InsightsDB, patterns []improve.FrictionPattern, _ string) error {
163→	repo, err := openRepository(ctx)
164→	if err != nil {
165→		return fmt.Errorf("open git repository: %w", err)
166→	}
167→	store := checkpoint.NewGitStore(repo)
168→
169→	// Limit to top 3 friction themes.
170→	limit := 3
171→	if len(patterns) < limit {
172→		limit = len(patterns)
173→	}
174→
175→	for i := range patterns[:limit] {
176→		cpIDs, queryErr := idb.QuerySessionsWithFriction(ctx, "%"+patterns[i].Theme+"%")
177→		if queryErr != nil {
178→			continue
179→		}
180→
181→		// Limit to top 2 sessions per theme.
182→		sessionLimit := 2
183→		if len(cpIDs) < sessionLimit {
184→			sessionLimit = len(cpIDs)
185→		}
186→
187→		var excerpts []string
188→		for _, cpIDStr := range cpIDs[:sessionLimit] {
189→			cpID, parseErr := checkpointid.NewCheckpointID(cpIDStr)
190→			if parseErr != nil {
191→				continue
192→			}
193→
194→			content, readErr := store.ReadSessionContent(ctx, cpID, 0)
195→			if readErr != nil {
196→				continue
197→			}
198→
199→			condensed, buildErr := summarize.BuildCondensedTranscriptFromBytes(content.Transcript, content.Metadata.Agent)
200→			if buildErr != nil || len(condensed) == 0 {
201→				continue
202→			}
203→
204→			formatted := summarize.FormatCondensedTranscript(summarize.Input{Transcript: condensed})
205→			excerpt := truncateString(formatted, 2000)
206→			if excerpt != "" {
207→				excerpts = append(excerpts, excerpt)
208→			}
209→		}
210→
211→		if len(excerpts) > 0 {
212→			patterns[i].TranscriptExcerpt = strings.Join(excerpts, "\n---\n")
213→		}
214→	}
215→
216→	return nil
217→}
