219→// applyExcerpts copies TranscriptExcerpt values from src patterns into dst patterns
220→// by matching on theme text.
221→func applyExcerpts(dst []improve.FrictionPattern, src []improve.FrictionPattern) {
222→	excerptByTheme := make(map[string]string, len(src))
223→	for _, p := range src {
224→		if p.TranscriptExcerpt != "" {
225→			excerptByTheme[p.Theme] = p.TranscriptExcerpt
226→		}
227→	}
228→	for i := range dst {
229→		if excerpt, ok := excerptByTheme[dst[i].Theme]; ok {
230→			dst[i].TranscriptExcerpt = excerpt
231→		}
232→	}
233→}
