235→// sessionRowsToSummaries converts insightsdb rows into improve.SessionSummaryData values.
236→func sessionRowsToSummaries(rows []insightsdb.SessionRow) []improve.SessionSummaryData {
237→	summaries := make([]improve.SessionSummaryData, 0, len(rows))
238→	for _, r := range rows {
239→		s := improve.SessionSummaryData{
240→			CheckpointID: r.CheckpointID,
241→			Friction:     r.Friction,
242→		}
243→		for _, l := range r.Learnings {
244→			s.Learnings = append(s.Learnings, improve.LearningEntry{
245→				Scope:   l.Scope,
246→				Finding: l.Finding,
247→				Path:    l.Path,
248→			})
249→		}
250→		summaries = append(summaries, s)
251→	}
252→	return summaries
253→}
