290→// renderImproveTerminal writes a styled terminal view of the improvement report.
291→func renderImproveTerminal(w io.Writer, report improve.ImprovementReport) {
292→	s := termstyle.New(w)
293→
294→	fmt.Fprintln(w, s.Render(s.Bold, "Entire Improve"))
295→	fmt.Fprintf(w, "Analyzed %d sessions | %d friction points | %d patterns found\n\n",
296→		report.SessionsUsed, report.FrictionTotal, report.PatternsFound)
297→
298→	// Context Files section.
299→	fmt.Fprintln(w, s.SectionRule("Context Files"))
300→	for _, cf := range report.ContextFiles {
301→		if cf.Exists {
302→			line := fmt.Sprintf("  %s  %d bytes", cf.Type, cf.SizeBytes)
303→			fmt.Fprintln(w, s.Render(s.Bold, line))
304→		} else {
305→			line := fmt.Sprintf("  %s  missing", cf.Type)
306→			fmt.Fprintln(w, s.Render(s.Gray, line))
307→		}
308→	}
309→	fmt.Fprintln(w)
310→
311→	// Suggestions section.
312→	fmt.Fprintln(w, s.SectionRule(fmt.Sprintf("Suggestions (%d)", len(report.Suggestions))))
313→	if len(report.Suggestions) == 0 {
314→		fmt.Fprintln(w, "  No suggestions generated.")
315→	}
316→	for i, sug := range report.Suggestions {
317→		// Title line with priority.
318→		titleLine := fmt.Sprintf("  %d. %s  %s", i+1, sug.Title, sug.Priority)
319→		fmt.Fprintln(w, s.Render(s.Bold, titleLine))
320→
321→		// Category and file.
322→		metaLine := fmt.Sprintf("     %s → %s", sug.Category, sug.FileType)
323→		fmt.Fprintln(w, s.Render(s.Dim, metaLine))
324→
325→		// Description.
326→		if sug.Description != "" {
327→			fmt.Fprintf(w, "     %s\n", sug.Description)
328→		}
329→
330→		// Diff rendering.
331→		if sug.Diff != "" {
332→			fmt.Fprintln(w)
333→			renderDiff(w, s, sug.Diff)
334→		}
335→		fmt.Fprintln(w)
336→	}
337→}
