361→// renderUsageLine prints a single-line cost/token summary after the report.
362→func renderUsageLine(w io.Writer, usage *llmcli.UsageInfo) {
363→	s := termstyle.New(w)
364→	tokens := termstyle.FormatTokenCount(usage.InputTokens + usage.OutputTokens)
