369→// renderDiff writes a unified diff with colored lines to w.
370→// Lines starting with '+' are rendered in green, '-' in red, '@@' in cyan,
371→// and all other lines in dim.
372→func renderDiff(w io.Writer, s termstyle.Styles, diff string) {
373→	for _, line := range strings.Split(diff, "\n") {
374→		switch {
375→		case strings.HasPrefix(line, "@@"):
376→			fmt.Fprintln(w, s.Render(s.Cyan, line))
377→		case strings.HasPrefix(line, "+"):
378→			fmt.Fprintln(w, s.Render(s.Green, line))
379→		case strings.HasPrefix(line, "-"):
380→			fmt.Fprintln(w, s.Render(s.Red, line))
381→		default:
382→			fmt.Fprintln(w, s.Render(s.Dim, line))
383→		}
384→	}
385→}
