  1→// Package summarize provides AI-powered summarization of development sessions.
  2→package summarize
  3→
  4→import (
  5→	"context"
  6→	"encoding/json"
  7→	"errors"
  8→	"fmt"
  9→	"strings"
 10→
 11→	"github.com/entireio/cli/cmd/entire/cli/agent"
 12→	"github.com/entireio/cli/cmd/entire/cli/agent/factoryaidroid"
 13→	"github.com/entireio/cli/cmd/entire/cli/agent/geminicli"
 14→	"github.com/entireio/cli/cmd/entire/cli/agent/opencode"
 15→	"github.com/entireio/cli/cmd/entire/cli/agent/types"
