220→// buildCondensedTranscriptFromDroid parses Droid transcript and extracts a condensed view.
221→func buildCondensedTranscriptFromDroid(content []byte) ([]Entry, error) {
222→	droidLines, _, err := factoryaidroid.ParseDroidTranscriptFromBytes(content, 0)
223→	if err != nil {
