229→// extractOpenCodeToolDetail extracts a detail string from an OpenCode tool's input map.
230→// OpenCode uses camelCase keys (e.g., "filePath" instead of "file_path").
231→func extractOpenCodeToolDetail(input map[string]interface{}) string {
232→	for _, key := range []string{"description", "command", "filePath", "path", "pattern"} {
233→		if v, ok := input[key].(string); ok && v != "" {
234→			return v
235→		}
236→	}
237→	return ""
238→}
