240→// extractGenericToolDetail extracts an appropriate detail string from a tool's input/args map.
241→// Checks common fields in order of preference. Used by Gemini condensation.
242→func extractGenericToolDetail(input map[string]interface{}) string {
243→	for _, key := range []string{"description", "command", "file_path", "path", "pattern"} {
244→		if v, ok := input[key].(string); ok && v != "" {
245→			return v
246→		}
247→	}
248→	return ""
249→}
