251→// BuildCondensedTranscript extracts a condensed view of the transcript.
252→// It processes user prompts, assistant responses, and tool calls into
253→// a simplified format suitable for LLM summarization.
254→func BuildCondensedTranscript(lines []transcript.Line) []Entry {
255→	var entries []Entry
256→
257→	for _, line := range lines {
258→		switch line.Type {
259→		case transcript.TypeUser:
260→			if entry := extractUserEntry(line); entry != nil {
261→				entries = append(entries, *entry)
262→			}
263→		case transcript.TypeAssistant:
264→			assistantEntries := extractAssistantEntries(line)
265→			entries = append(entries, assistantEntries...)
266→		}
267→	}
268→
269→	return entries
270→}
271→
272→// skillContentPrefix identifies user messages that are skill content injections.
273→// These are injected after a Skill tool call and contain the full skill instructions.
274→const skillContentPrefix = "Base directory for this skill:"
275→
276→// extractUserEntry extracts a user entry from a transcript line.
277→// Returns nil if the line doesn't contain a valid user prompt or is skill content.
278→func extractUserEntry(line transcript.Line) *Entry {
279→	content := transcript.ExtractUserContent(line.Message)
280→	if content == "" {
281→		return nil
282→	}
283→
284→	// Skip skill content injections - these are verbose skill instructions
285→	// injected as user messages after Skill tool invocations in Claude Code.
286→	// The prefix "Base directory for this skill:" is added by the superpowers
287→	// plugin when loading skill content. This filtering reduces transcript noise
288→	// since skill content is documentation, not user intent.
289→	if strings.HasPrefix(content, skillContentPrefix) {
290→		return nil
291→	}
292→
293→	return &Entry{
294→		Type:    EntryTypeUser,
295→		Content: content,
296→	}
297→}
298→
299→// extractAssistantEntries extracts assistant and tool entries from a transcript line.
300→func extractAssistantEntries(line transcript.Line) []Entry {
301→	var msg transcript.AssistantMessage
302→	if err := json.Unmarshal(line.Message, &msg); err != nil {
303→		return nil
304→	}
305→
306→	var entries []Entry
307→
308→	for _, block := range msg.Content {
309→		switch block.Type {
310→		case transcript.ContentTypeText:
311→			if block.Text != "" {
312→				entries = append(entries, Entry{
313→					Type:    EntryTypeAssistant,
314→					Content: block.Text,
315→				})
316→			}
317→		case transcript.ContentTypeToolUse:
318→			var input transcript.ToolInput
319→			_ = json.Unmarshal(block.Input, &input) //nolint:errcheck // Best-effort parsing
320→
321→			detail := extractToolDetail(block.Name, input)
322→
323→			entries = append(entries, Entry{
324→				Type:       EntryTypeTool,
325→				ToolName:   block.Name,
326→				ToolDetail: detail,
327→			})
328→		}
329→	}
330→
331→	return entries
332→}
333→
334→// extractToolDetail extracts an appropriate detail string for a tool call.
335→// For tools in minimalDetailTools, only essential identifiers are shown.
336→// For other tools, the full detail chain is used.
337→func extractToolDetail(toolName string, input transcript.ToolInput) string {
338→	// For minimal detail tools, extract only the essential identifier
339→	if minimalDetailTools[toolName] {
340→		switch toolName {
341→		case "Skill":
342→			return input.Skill
343→		case "Read":
344→			if input.FilePath != "" {
345→				return input.FilePath
346→			}
347→			return input.NotebookPath
348→		case "WebFetch":
349→			return input.URL
350→		}
351→	}
352→
353→	// For other tools, use the full detail chain
354→	if input.Description != "" {
355→		return input.Description
356→	}
357→	if input.Command != "" {
358→		return input.Command
359→	}
360→	if input.FilePath != "" {
361→		return input.FilePath
362→	}
363→	if input.NotebookPath != "" {
364→		return input.NotebookPath
365→	}
366→	return input.Pattern
367→}
368→
369→// FormatCondensedTranscript formats an Input into a human-readable string for LLM.
370→// The format is:
371→//
372→//	[User] user prompt here
373→//
374→//	[Assistant] assistant response here
375→//
376→//	[Tool] ToolName: description or file path
377→func FormatCondensedTranscript(input Input) string {
378→	var sb strings.Builder
379→
380→	for i, entry := range input.Transcript {
381→		if i > 0 {
382→			sb.WriteString("\n")
383→		}
384→
385→		switch entry.Type {
386→		case EntryTypeUser:
387→			sb.WriteString("[User] ")
388→			sb.WriteString(entry.Content)
389→			sb.WriteString("\n")
390→		case EntryTypeAssistant:
391→			sb.WriteString("[Assistant] ")
392→			sb.WriteString(entry.Content)
393→			sb.WriteString("\n")
394→		case EntryTypeTool:
395→			sb.WriteString("[Tool] ")
396→			sb.WriteString(entry.ToolName)
397→			if entry.ToolDetail != "" {
398→				sb.WriteString(": ")
399→				sb.WriteString(entry.ToolDetail)
400→			}
401→			sb.WriteString("\n")
402→		}
403→	}
404→
405→	if len(input.FilesTouched) > 0 {
406→		sb.WriteString("\n[Files Modified]\n")
407→		for _, file := range input.FilesTouched {
408→			fmt.Fprintf(&sb, "- %s\n", file)
409→		}
410→	}
411→
412→	return sb.String()
413→}
