 51→// GetBranchTip returns the stored branch tip hash from cache_meta,
 52→// or an empty string if it has not been set yet.
 53→func (idb *InsightsDB) GetBranchTip(ctx context.Context) (string, error) {
 54→	var tip string
 55→	err := idb.db.QueryRowContext(ctx,
 56→		"SELECT value FROM cache_meta WHERE key = ?",
 57→		"branch_tip",
 58→	).Scan(&tip)
 59→	if err == sql.ErrNoRows {
 60→		return "", nil
 61→	}
 62→	if err != nil {
 63→		return "", fmt.Errorf("get branch tip: %w", err)
 64→	}
 65→	return tip, nil
 66→}
