 68→// SetBranchTip stores the branch tip hash in cache_meta.
 69→// Overwrites any previously stored value.
 70→func (idb *InsightsDB) SetBranchTip(ctx context.Context, tip string) error {
 71→	_, err := idb.db.ExecContext(ctx,
 72→		"INSERT OR REPLACE INTO cache_meta (key, value) VALUES (?, ?)",
 73→		"branch_tip",
 74→		tip,
 75→	)
 76→	if err != nil {
