 96→// InsertSession inserts a session and all its denormalized data into the cache.
 97→// The insert is performed inside a single transaction so the cache remains
 98→// consistent even if the caller is interrupted mid-insert.
 99→func (idb *InsightsDB) InsertSession(ctx context.Context, row SessionRow) error {
100→	tx, err := idb.db.BeginTx(ctx, nil)
101→	if err != nil {
102→		return fmt.Errorf("begin transaction: %w", err)
103→	}
104→	defer func() {
105→		if err != nil {
106→			_ = tx.Rollback() //nolint:errcheck // Rollback after failed tx; error is irrelevant
107→		}
108→	}()
109→
110→	if err = insertSessionRow(ctx, tx, row); err != nil {
111→		return err
112→	}
113→	if err = insertFilesTouched(ctx, tx, row); err != nil {
114→		return err
115→	}
116→	if err = insertFriction(ctx, tx, row); err != nil {
117→		return err
118→	}
119→	if err = insertLearnings(ctx, tx, row); err != nil {
120→		return err
121→	}
122→
123→	if err = tx.Commit(); err != nil {
124→		return fmt.Errorf("commit transaction: %w", err)
125→	}
126→	return nil
127→}
