129→func insertSessionRow(ctx context.Context, tx *sql.Tx, row SessionRow) error {
130→	hasSummary := 0
131→	if row.HasSummary {
132→		hasSummary = 1
133→	}
134→	_, err := tx.ExecContext(ctx, `
135→		INSERT INTO sessions (
136→			checkpoint_id, session_id, session_index,
137→			agent, model, branch, created_at,
138→			input_tokens, cache_tokens, output_tokens, total_tokens,
139→			api_call_count, duration_ms, turn_count,
140→			intent, outcome, agent_percentage,
141→			overall_score, score_token_efficiency, score_first_pass,
142→			score_friction, score_focus, has_summary
143→		) VALUES (
144→			?, ?, ?,
145→			?, ?, ?, ?,
146→			?, ?, ?, ?,
147→			?, ?, ?,
148→			?, ?, ?,
149→			?, ?, ?,
150→			?, ?, ?
151→		)`,
152→		row.CheckpointID, row.SessionID, row.SessionIndex,
153→		nullableString(row.Agent), nullableString(row.Model), nullableString(row.Branch),
154→		row.CreatedAt.UTC().Format(time.RFC3339),
155→		row.InputTokens, row.CacheTokens, row.OutputTokens, row.TotalTokens,
156→		row.APICallCount, row.DurationMs, row.TurnCount,
157→		nullableString(row.Intent), nullableString(row.Outcome), row.AgentPct,
158→		row.OverallScore, row.ScoreTokenEff,
159→		row.ScoreFirstPass, row.ScoreFriction,
160→		row.ScoreFocus, hasSummary,
161→	)
162→	if err != nil {
163→		return fmt.Errorf("insert session row: %w", err)
164→	}
165→	return nil
166→}
