195→			"INSERT INTO learnings (checkpoint_id, session_index, scope, finding, path) VALUES (?, ?, ?, ?, ?)",
196→			row.CheckpointID, row.SessionIndex, l.Scope, l.Finding, nullableString(l.Path),
