204→// UpdateSessionSummary updates an existing session row with summary-derived data
205→// (intent, outcome, scores, friction, learnings) and sets has_summary = 1.
206→func (idb *InsightsDB) UpdateSessionSummary(ctx context.Context, row SessionRow) error {
207→	tx, err := idb.db.BeginTx(ctx, nil)
208→	if err != nil {
209→		return fmt.Errorf("begin transaction: %w", err)
210→	}
211→	defer func() {
212→		if err != nil {
213→			_ = tx.Rollback() //nolint:errcheck // Rollback after failed tx; error is irrelevant
214→		}
215→	}()
216→
217→	_, err = tx.ExecContext(ctx, `
218→		UPDATE sessions SET
219→			intent = ?, outcome = ?,
220→			overall_score = ?, score_token_efficiency = ?, score_first_pass = ?,
221→			score_friction = ?, score_focus = ?, has_summary = 1
222→		WHERE checkpoint_id = ? AND session_index = ?`,
223→		nullableString(row.Intent), nullableString(row.Outcome),
224→		row.OverallScore, row.ScoreTokenEff, row.ScoreFirstPass,
225→		row.ScoreFriction, row.ScoreFocus,
226→		row.CheckpointID, row.SessionIndex,
227→	)
228→	if err != nil {
229→		return fmt.Errorf("update session summary: %w", err)
230→	}
231→
232→	// Delete old friction/learnings and re-insert.
233→	for _, table := range []string{"friction", "learnings"} {
234→		if _, err = tx.ExecContext(ctx,
235→			"DELETE FROM "+table+" WHERE checkpoint_id = ? AND session_index = ?", //nolint:gosec // table name is hardcoded
236→			row.CheckpointID, row.SessionIndex,
237→		); err != nil {
238→			return fmt.Errorf("delete old %s: %w", table, err)
239→		}
240→	}
241→
242→	if err = insertFriction(ctx, tx, row); err != nil {
243→		return err
244→	}
245→	if err = insertLearnings(ctx, tx, row); err != nil {
246→		return err
247→	}
248→
249→	if err = tx.Commit(); err != nil {
250→		return fmt.Errorf("commit transaction: %w", err)
251→	}
252→	return nil
253→}
