// Package insightsdb provides a SQLite cache layer for session analytics.
// It stores session metadata for fast querying by the insights and improve commands.
package insightsdb

import (
	"context"
	"database/sql"
	"fmt"

	_ "modernc.org/sqlite" // SQLite driver
)

// InsightsDB wraps a SQLite database for insights caching.
type InsightsDB struct {
	db *sql.DB
}

// Open opens (or creates) the insights cache at the given path.
// It sets WAL mode and busy timeout for safe concurrent access,
// then runs migrations to ensure all tables exist.
func Open(dbPath string) (*InsightsDB, error) {
	db, err := sql.Open("sqlite", dbPath)
	if err != nil {
		return nil, fmt.Errorf("open sqlite database: %w", err)
	}

	if err = applyPragmas(db); err != nil {
		_ = db.Close()
		return nil, err
	}

	idb := &InsightsDB{db: db}
	if err = idb.migrate(); err != nil {
		_ = db.Close()
		return nil, fmt.Errorf("run migrations: %w", err)
	}

	return idb, nil
}

// applyPragmas sets performance and safety pragmas on the database.
func applyPragmas(db *sql.DB) error {
	ctx := context.Background()
	pragmas := []string{
		"PRAGMA journal_mode=WAL",
		"PRAGMA busy_timeout=5000",
	}
	for _, pragma := range pragmas {
		if _, err := db.ExecContext(ctx, pragma); err != nil {
			return fmt.Errorf("apply pragma %q: %w", pragma, err)
		}
	}
	return nil
}

// Close closes the underlying database connection.
func (idb *InsightsDB) Close() error {
	if err := idb.db.Close(); err != nil {
		return fmt.Errorf("close insights database: %w", err)
	}
	return nil
}

// migrate creates all tables if they do not already exist.
// It is safe to call multiple times (idempotent).
func (idb *InsightsDB) migrate() error {
	ctx := context.Background()
	statements := []string{
		`CREATE TABLE IF NOT EXISTS cache_meta (
			key   TEXT PRIMARY KEY,
			value TEXT NOT NULL
		)`,
		`CREATE TABLE IF NOT EXISTS sessions (
			checkpoint_id        TEXT NOT NULL,
			session_id           TEXT NOT NULL,
			session_index        INTEGER NOT NULL,
			agent                TEXT,
			model                TEXT,
			branch               TEXT,
			created_at           TEXT NOT NULL,
			input_tokens         INTEGER DEFAULT 0,
			cache_tokens         INTEGER DEFAULT 0,
			output_tokens        INTEGER DEFAULT 0,
			total_tokens         INTEGER DEFAULT 0,
			api_call_count       INTEGER DEFAULT 0,
			duration_ms          INTEGER DEFAULT 0,
			turn_count           INTEGER DEFAULT 0,
			intent               TEXT,
			outcome              TEXT,
			agent_percentage     REAL DEFAULT 0,
			overall_score        REAL,
			score_token_efficiency REAL,
			score_first_pass     REAL,
			score_friction       REAL,
			score_focus          REAL,
			has_summary          INTEGER DEFAULT 0,
			PRIMARY KEY (checkpoint_id, session_index)
		)`,
		`CREATE INDEX IF NOT EXISTS idx_sessions_created ON sessions(created_at)`,
		`CREATE INDEX IF NOT EXISTS idx_sessions_agent   ON sessions(agent)`,
		`CREATE TABLE IF NOT EXISTS files_touched (
			checkpoint_id TEXT NOT NULL,
			session_index INTEGER NOT NULL,
			file_path     TEXT NOT NULL
		)`,
		`CREATE TABLE IF NOT EXISTS friction (
			checkpoint_id TEXT NOT NULL,
			session_index INTEGER NOT NULL,
			text          TEXT NOT NULL
		)`,
		`CREATE INDEX IF NOT EXISTS idx_friction_text ON friction(text)`,
		`CREATE TABLE IF NOT EXISTS learnings (
			checkpoint_id TEXT NOT NULL,
			session_index INTEGER NOT NULL,
			scope         TEXT NOT NULL,
			finding       TEXT NOT NULL,
			path          TEXT
		)`,
		`CREATE TABLE IF NOT EXISTS suggestions (
			id          TEXT PRIMARY KEY,
			file_type   TEXT NOT NULL,
			category    TEXT NOT NULL,
			title       TEXT NOT NULL,
			description TEXT,
			diff        TEXT,
			priority    TEXT DEFAULT 'medium',
			status      TEXT DEFAULT 'pending',
			created_at  TEXT NOT NULL,
			resolved_at TEXT
		)`,
	}

	for _, stmt := range statements {
		if _, err := idb.db.ExecContext(ctx, stmt); err != nil {
			return fmt.Errorf("execute migration statement: %w", err)
		}
	}
	return nil
}

// ListTables returns the names of all user tables in the database.
// This is used in tests to verify migrations ran correctly.
func (idb *InsightsDB) ListTables(ctx context.Context) ([]string, error) {
	rows, err := idb.db.QueryContext(ctx,
		"SELECT name FROM sqlite_master WHERE type='table' ORDER BY name",
	)
	if err != nil {
		return nil, fmt.Errorf("query tables: %w", err)
	}
	defer rows.Close()

	var tables []string
	for rows.Next() {
		var name string
		if err = rows.Scan(&name); err != nil {
			return nil, fmt.Errorf("scan table name: %w", err)
		}
		tables = append(tables, name)
	}
	if err = rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate tables: %w", err)
	}
	return tables, nil
}

package insightsdb

import (
	"context"
	"database/sql"
	"fmt"
	"time"
)

// SessionRow represents a single session for insertion into the cache.
// This is the denormalized view used by the CLI — callers populate it
// from checkpoint.CommittedMetadata.
type SessionRow struct {
	CheckpointID string
	SessionID    string
	SessionIndex int
	Agent        string
	Model        string
	Branch       string
	CreatedAt    time.Time
	InputTokens  int
	CacheTokens  int
	OutputTokens int
	TotalTokens  int
	APICallCount int
	DurationMs   int64
	TurnCount    int
	Intent       string
	Outcome      string
	AgentPct     float64
	// Score fields
	OverallScore   float64
	ScoreTokenEff  float64
	ScoreFirstPass float64
	ScoreFriction  float64
	ScoreFocus     float64
	HasSummary     bool
	// Denormalized arrays
	FilesTouched []string
	Friction     []string
	Learnings    []LearningRow
}

// LearningRow represents a single learning entry within a session.
type LearningRow struct {
	Scope   string // "repo", "workflow", "code"
	Finding string
	Path    string // only meaningful when Scope is "code"
}

// GetBranchTip returns the stored branch tip hash from cache_meta,
// or an empty string if it has not been set yet.
func (idb *InsightsDB) GetBranchTip(ctx context.Context) (string, error) {
	var tip string
	err := idb.db.QueryRowContext(ctx,
		"SELECT value FROM cache_meta WHERE key = ?",
		"branch_tip",
	).Scan(&tip)
	if err == sql.ErrNoRows {
		return "", nil
	}
	if err != nil {
		return "", fmt.Errorf("get branch tip: %w", err)
	}
	return tip, nil
}

// SetBranchTip stores the branch tip hash in cache_meta.
// Overwrites any previously stored value.
func (idb *InsightsDB) SetBranchTip(ctx context.Context, tip string) error {
	_, err := idb.db.ExecContext(ctx,
		"INSERT OR REPLACE INTO cache_meta (key, value) VALUES (?, ?)",
		"branch_tip",
		tip,
	)
	if err != nil {
		return fmt.Errorf("set branch tip: %w", err)
	}
	return nil
}

// HasCheckpoint returns true if any session for the given checkpoint ID
// is already present in the sessions table.
func (idb *InsightsDB) HasCheckpoint(ctx context.Context, checkpointID string) (bool, error) {
	var count int
	err := idb.db.QueryRowContext(ctx,
		"SELECT COUNT(*) FROM sessions WHERE checkpoint_id = ?",
		checkpointID,
	).Scan(&count)
	if err != nil {
		return false, fmt.Errorf("check checkpoint existence: %w", err)
	}
	return count > 0, nil
}

// InsertSession inserts a session and all its denormalized data into the cache.
// The insert is performed inside a single transaction so the cache remains
// consistent even if the caller is interrupted mid-insert.
func (idb *InsightsDB) InsertSession(ctx context.Context, row SessionRow) error {
	tx, err := idb.db.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("begin transaction: %w", err)
	}
	defer func() {
		if err != nil {
			_ = tx.Rollback() //nolint:errcheck // Rollback after failed tx; error is irrelevant
		}
	}()

	if err = insertSessionRow(ctx, tx, row); err != nil {
		return err
	}
	if err = insertFilesTouched(ctx, tx, row); err != nil {
		return err
	}
	if err = insertFriction(ctx, tx, row); err != nil {
		return err
	}
	if err = insertLearnings(ctx, tx, row); err != nil {
		return err
	}

	if err = tx.Commit(); err != nil {
		return fmt.Errorf("commit transaction: %w", err)
	}
	return nil
}

func insertSessionRow(ctx context.Context, tx *sql.Tx, row SessionRow) error {
	hasSummary := 0
	if row.HasSummary {
		hasSummary = 1
	}
	_, err := tx.ExecContext(ctx, `
		INSERT INTO sessions (
			checkpoint_id, session_id, session_index,
			agent, model, branch, created_at,
			input_tokens, cache_tokens, output_tokens, total_tokens,
